'use client';

import React, { useState, useEffect, useEffectEvent } from 'react';
import { api } from '@/lib/api';
import { useToast } from '@/components/ui/Toast';
import { useAuth } from '@/context/AuthContext';
import { CampusEvent } from '@/types/chat';
import { canManageEvents } from '@/lib/campus-rooms';
import {
  Calendar as CalendarIcon,
  Clock,
  MapPin,
  Plus,
  AlertTriangle,
  CheckCircle2,
  Filter,
  X,
  Sparkles,
  Building,
  GraduationCap,
  Lock,
} from 'lucide-react';

interface GymkhanaCalendarModalProps {
  isOpen: boolean;
  onClose: () => void;
  defaultOrganizer?: string;
  isAdmin?: boolean;
}

const VENUES = [
  'All Venues',
  'Auditorium A1/A2',
  'A13 Hall',
  'South Campus Grounds',
  'SCEE Seminar Hall',
  'Sports Complex',
] as const;

const CATEGORIES = [
  'All Categories',
  'Club Workshop',
  'Fest Event',
  'Sports Tournament',
  'Placement & Tech Talk',
  'General',
] as const;

export const GymkhanaCalendarModal: React.FC<GymkhanaCalendarModalProps> = ({
  isOpen,
  onClose,
  defaultOrganizer,
  isAdmin,
}) => {
  const { error, success } = useToast();
  const { profile } = useAuth();
  const [events, setEvents] = useState<CampusEvent[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedVenue, setSelectedVenue] = useState<string>('All Venues');
  const [selectedCategory, setSelectedCategory] = useState<string>('All Categories');
  const [showBookingForm, setShowBookingForm] = useState(false);

  const roll = profile?.username?.toLowerCase() || '';
  const canBook =
    isAdmin !== undefined
      ? isAdmin
      : canManageEvents(roll, defaultOrganizer);

  // Booking Form State
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [category, setCategory] = useState<CampusEvent['category']>('Club Workshop');
  const [organizer, setOrganizer] = useState(defaultOrganizer || '');
  const [venue, setVenue] = useState<CampusEvent['venue']>('Auditorium A1/A2');
  const [date, setDate] = useState(() => new Date().toISOString().split('T')[0]);
  const [startTime, setStartTime] = useState('05:30 PM');
  const [endTime, setEndTime] = useState('08:30 PM');
  const [submitting, setSubmitting] = useState(false);




  const loadEvents = async () => {
    setLoading(true);
    try {
      const v = selectedVenue === 'All Venues' ? undefined : selectedVenue;
      const c = selectedCategory === 'All Categories' ? undefined : selectedCategory;
      const res = await api.getCampusEvents(v, c);
      setEvents(res.data || []);
    } catch (err: unknown) {
      error((err instanceof Error ? err.message : '') || 'Failed to load Gymkhana calendar events.');
    } finally {
      setLoading(false);
    }
  };
  const loadOnOpen = useEffectEvent(() => loadEvents());
  useEffect(() => { if (isOpen) loadOnOpen(); }, [isOpen, selectedVenue, selectedCategory]);

  const handleBookEvent = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!title.trim() || !organizer.trim() || !date) {
      error('Please fill in event title, organizer, and date.');
      return;
    }

    setSubmitting(true);
    try {
      const res = await api.createCampusEvent({
        title: title.trim(),
        description: description.trim(),
        category,
        organizer: organizer.trim(),
        venue,
        date,
        startTime,
        endTime,
      });

      if ('warning' in res && typeof res.warning === 'string') {
        error(res.warning);
      } else {
        success(`Event "${title}" proposed and scheduled at ${venue}!`);
      }

      setShowBookingForm(false);
      setTitle('');
      setDescription('');
      loadEvents();
    } catch (err: unknown) {
      error((err instanceof Error ? err.message : '') || 'Booking submission failed.');
    } finally {
      setSubmitting(false);
    }
  };

  if (!isOpen) return null;

  return (
    <div
      style={{
        position: 'fixed',
        inset: 0,
        zIndex: 9999,
        background: 'rgba(5, 7, 15, 0.82)',
        backdropFilter: 'blur(8px)',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        padding: '20px',
      }}
    >
      <div
        className="glass-panel"
        style={{
          width: '100%',
          maxWidth: '860px',
          maxHeight: '90vh',
          display: 'flex',
          flexDirection: 'column',
          background: 'var(--bg-elevated)',
          border: '1px solid var(--border-subtle)',
          borderRadius: 'var(--radius-lg)',
          boxShadow: 'var(--shadow-lg), 0 0 60px var(--accent-light)',
          overflow: 'hidden',
          animation: 'fadeIn 0.2s ease-out',
        }}
      >
        {/* Header */}
        <div
          style={{
            padding: '20px 24px',
            borderBottom: '1px solid var(--border-subtle)',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'space-between',
            background: 'var(--accent)',
          }}
        >
          <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
            <div
              style={{
                width: '42px',
                height: '42px',
                borderRadius: '12px',
                background: 'var(--accent)',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                color: 'var(--text-primary)',
                boxShadow: '0 4px 14px var(--accent-light)',
              }}
            >
              <CalendarIcon size={22} />
            </div>
            <div>
              <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                <h2 style={{ fontSize: '1.2rem', fontWeight: 800, letterSpacing: '-0.02em', color: 'var(--text-primary)' }}>
                  Unified Gymkhana Calendar
                </h2>
                <span
                  style={{
                    fontSize: '0.8rem',
                    fontWeight: 700,
                    padding: '2px 8px',
                    borderRadius: '9999px',
                    background: 'var(--accent-light)',
                    color: 'var(--accent)',
                    border: '1px solid var(--accent-light)',
                  }}
                >
                  IIT Mandi Intracampus
                </span>
              </div>
              <p style={{ fontSize: '0.8rem', color: 'var(--text-muted)', marginTop: '2px' }}>
                Central venue bookings for Auditorium A1/A2, A13 Hall, South Grounds & Seminar Halls
              </p>
            </div>
          </div>

          <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
            {canBook ? (
              <button
                onClick={() => setShowBookingForm(!showBookingForm)}
                className="btn btn-primary"
                style={{ padding: '8px 14px', fontSize: '0.833rem' }}
              >
                {showBookingForm ? <X size={15} /> : <Plus size={15} />}
                <span>{showBookingForm ? 'Close Form' : 'Book Venue / Event'}</span>
              </button>
            ) : (
              <div
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  gap: '6px',
                  padding: '7px 12px',
                  borderRadius: 'var(--radius-md)',
                  background: 'var(--border-subtle)',
                  border: '1px solid var(--border-subtle)',
                  fontSize: '0.8rem',
                  color: 'var(--text-muted)',
                }}
                title="Only Club Coordinators, Branch Representatives, and Gymkhana Admins can book venues"
              >
                <Lock size={13} className="text-[var(--accent)]" />
                <span>Coordinator Privileges Required to Book</span>
              </div>
            )}
            <button
              onClick={onClose}
              className="btn btn-ghost"
              style={{ padding: '8px', borderRadius: '50%' }}
            >
              <X size={18} />
            </button>
          </div>
        </div>

        {/* Filters Bar */}
        <div
          style={{
            padding: '12px 24px',
            borderBottom: '1px solid var(--border-subtle)',
            background: 'rgba(0, 0, 0, 0.2)',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'space-between',
            gap: '12px',
            flexWrap: 'wrap',
          }}
        >
          <div style={{ display: 'flex', alignItems: 'center', gap: '8px', flexWrap: 'wrap' }}>
            <span style={{ fontSize: '0.8rem', color: 'var(--text-muted)', display: 'flex', alignItems: 'center', gap: '4px' }}>
              <Filter size={13} /> Venue:
            </span>
            {VENUES.map((v) => (
              <button
                key={v}
                onClick={() => setSelectedVenue(v)}
                style={{
                  fontSize: '0.8rem',
                  fontWeight: 600,
                  padding: '3px 10px',
                  borderRadius: '9999px',
                  background: selectedVenue === v ? 'var(--accent-light)' : 'var(--border-subtle)',
                  color: selectedVenue === v ? 'var(--accent)' : 'var(--text-secondary)',
                  border: selectedVenue === v ? '1px solid var(--accent-light)' : '1px solid var(--border-subtle)',
                  cursor: 'pointer',
                  transition: 'all 0.15s',
                }}
              >
                {v}
              </button>
            ))}
          </div>

          <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
            <select
              value={selectedCategory}
              onChange={(e) => setSelectedCategory(e.target.value)}
              className="input-control"
              style={{ fontSize: '0.8rem', padding: '4px 10px', width: 'auto', height: 'auto' }}
            >
              {CATEGORIES.map((c) => (
                <option key={c} value={c} style={{ background: '#0f172a' }}>
                  {c}
                </option>
              ))}
            </select>
          </div>
        </div>

        {/* Content Body */}
        <div style={{ flex: 1, overflowY: 'auto', padding: '24px' }}>
          {/* Booking Form Overlay / Dropdown */}
          {showBookingForm && (
            <form
              onSubmit={handleBookEvent}
              style={{
                padding: '20px',
                borderRadius: 'var(--radius-md)',
                background: 'rgba(30, 41, 59, 0.7)',
                border: '1px solid var(--accent-light)',
                marginBottom: '24px',
                display: 'flex',
                flexDirection: 'column',
                gap: '14px',
                animation: 'fadeIn 0.2s ease-out',
              }}
            >
              <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                <h3 style={{ fontSize: '1.0rem', fontWeight: 700, color: 'var(--accent)', display: 'flex', alignItems: 'center', gap: '6px' }}>
                  <Building size={16} /> In-App Event & Venue Booking Proposal
                </h3>
                <span style={{ fontSize: '0.8rem', color: 'var(--text-muted)' }}>
                  Society Heads & Branch Representatives
                </span>
              </div>

              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(240px, 1fr))', gap: '14px' }}>
                <div className="input-group" style={{ margin: 0 }}>
                  <label className="input-label">Event Title</label>
                  <input
                    type="text"
                    required
                    placeholder="e.g. Robotronics ROS2 Hands-on Sprint"
                    className="input-control"
                    value={title}
                    onChange={(e) => setTitle(e.target.value)}
                  />
                </div>

                <div className="input-group" style={{ margin: 0 }}>
                  <label className="input-label">Organizing Society / Club / Cohort</label>
                  <input
                    type="text"
                    required
                    placeholder="e.g. KamandPrompt, Exodia Team, B.Tech CSE"
                    className="input-control"
                    value={organizer}
                    onChange={(e) => setOrganizer(e.target.value)}
                  />
                </div>

                <div className="input-group" style={{ margin: 0 }}>
                  <label className="input-label">Target Venue (Reservation)</label>
                  <select
                    className="input-control"
                    value={venue}
                    onChange={(e) => setVenue(e.target.value as CampusEvent['venue'])}
                  >
                    <option value="Auditorium A1/A2" style={{ background: '#0f172a' }}>Auditorium A1/A2</option>
                    <option value="A13 Hall" style={{ background: '#0f172a' }}>A13 Hall</option>
                    <option value="South Campus Grounds" style={{ background: '#0f172a' }}>South Campus Grounds</option>
                    <option value="SCEE Seminar Hall" style={{ background: '#0f172a' }}>SCEE Seminar Hall</option>
                    <option value="Sports Complex" style={{ background: '#0f172a' }}>Sports Complex</option>
                    <option value="Other" style={{ background: '#0f172a' }}>Other Campus Location</option>
                  </select>
                </div>

                <div className="input-group" style={{ margin: 0 }}>
                  <label className="input-label">Category</label>
                  <select
                    className="input-control"
                    value={category}
                    onChange={(e) => setCategory(e.target.value as CampusEvent['category'])}
                  >
                    <option value="Club Workshop" style={{ background: '#0f172a' }}>Club Workshop</option>
                    <option value="Fest Event" style={{ background: '#0f172a' }}>Fest Event (Exodia / Frosthack)</option>
                    <option value="Sports Tournament" style={{ background: '#0f172a' }}>Sports Tournament (Rann-Neeti)</option>
                    <option value="Placement & Tech Talk" style={{ background: '#0f172a' }}>Placement & Tech Talk</option>
                    <option value="General" style={{ background: '#0f172a' }}>General Student Gathering</option>
                  </select>
                </div>

                <div className="input-group" style={{ margin: 0 }}>
                  <label className="input-label">Event Date</label>
                  <input
                    type="date"
                    required
                    className="input-control"
                    value={date}
                    onChange={(e) => setDate(e.target.value)}
                  />
                </div>

                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '8px' }}>
                  <div className="input-group" style={{ margin: 0 }}>
                    <label className="input-label">Start Time</label>
                    <input
                      type="text"
                      placeholder="05:30 PM"
                      className="input-control"
                      value={startTime}
                      onChange={(e) => setStartTime(e.target.value)}
                    />
                  </div>
                  <div className="input-group" style={{ margin: 0 }}>
                    <label className="input-label">End Time</label>
                    <input
                      type="text"
                      placeholder="08:30 PM"
                      className="input-control"
                      value={endTime}
                      onChange={(e) => setEndTime(e.target.value)}
                    />
                  </div>
                </div>
              </div>

              <div className="input-group" style={{ margin: 0 }}>
                <label className="input-label">Description & AV Requirements</label>
                <textarea
                  rows={2}
                  placeholder="Details, projector, mics, chairs, or guest info..."
                  className="input-control"
                  style={{ resize: 'vertical' }}
                  value={description}
                  onChange={(e) => setDescription(e.target.value)}
                />
              </div>

              <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '10px', marginTop: '4px' }}>
                <button
                  type="button"
                  onClick={() => setShowBookingForm(false)}
                  className="btn btn-ghost"
                  style={{ padding: '8px 14px' }}
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  disabled={submitting}
                  className="btn btn-primary"
                  style={{ padding: '8px 18px' }}
                >
                  {submitting ? 'Checking collisions...' : 'Submit Booking'}
                </button>
              </div>
            </form>
          )}

          {/* Events List */}
          {loading ? (
            <div style={{ textAlign: 'center', padding: '40px', color: 'var(--text-muted)' }}>
              Loading Gymkhana calendar events...
            </div>
          ) : events.length === 0 ? (
            <div style={{ textAlign: 'center', padding: '40px', color: 'var(--text-muted)' }}>
              No scheduled events found for this filter.
            </div>
          ) : (
            <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
              {events.map((evt) => (
                <div
                  key={evt.id}
                  style={{
                    padding: '16px',
                    borderRadius: 'var(--radius-md)',
                    background: 'rgba(15, 23, 42, 0.65)',
                    border: evt.status === 'conflict' ? '1px solid rgba(244, 63, 94, 0.4)' : '1px solid var(--border-subtle)',
                    display: 'flex',
                    flexDirection: 'column',
                    gap: '10px',
                    transition: 'all 0.15s ease',
                  }}
                >
                  <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', gap: '12px' }}>
                    <div>
                      <div style={{ display: 'flex', alignItems: 'center', gap: '8px', flexWrap: 'wrap' }}>
                        <span
                          style={{
                            fontSize: '0.8rem',
                            fontWeight: 700,
                            padding: '2px 8px',
                            borderRadius: '9999px',
                            background:
                              evt.category === 'Fest Event'
                                ? 'rgba(236, 72, 153, 0.2)'
                                : evt.category === 'Sports Tournament'
                                ? 'rgba(34, 197, 94, 0.2)'
                                : 'var(--accent-light)',
                            color:
                              evt.category === 'Fest Event'
                                ? '#f472b6'
                                : evt.category === 'Sports Tournament'
                                ? '#4ade80'
                                : 'var(--accent)',
                          }}
                        >
                          {evt.category}
                        </span>

                        {evt.status === 'conflict' && (
                          <span
                            style={{
                              fontSize: '0.8rem',
                              fontWeight: 700,
                              padding: '2px 8px',
                              borderRadius: '9999px',
                              background: 'rgba(244, 63, 94, 0.2)',
                              color: '#fb7185',
                              display: 'inline-flex',
                              alignItems: 'center',
                              gap: '4px',
                            }}
                          >
                            <AlertTriangle size={11} /> Collision Detected
                          </span>
                        )}

                        <span style={{ fontSize: '0.8rem', color: 'var(--text-muted)' }}>
                          Organized by <strong style={{ color: '#e2e8f0' }}>{evt.organizer}</strong>
                        </span>
                      </div>

                      <h4 style={{ fontSize: '1.067rem', fontWeight: 700, color: 'var(--text-primary)', marginTop: '6px' }}>
                        {evt.title}
                      </h4>
                    </div>

                    <div style={{ textAlign: 'right', flexShrink: 0 }}>
                      <div style={{ fontSize: '0.867rem', fontWeight: 700, color: 'var(--accent)' }}>
                        {evt.date}
                      </div>
                      <div style={{ fontSize: '0.8rem', color: 'var(--text-muted)', display: 'flex', alignItems: 'center', gap: '4px', justifyContent: 'flex-end', marginTop: '2px' }}>
                        <Clock size={12} /> {evt.startTime} - {evt.endTime}
                      </div>
                    </div>
                  </div>

                  {evt.description && (
                    <p style={{ fontSize: '0.833rem', color: 'var(--text-secondary)', lineHeight: 1.5 }}>
                      {evt.description}
                    </p>
                  )}

                  <div
                    style={{
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'space-between',
                      paddingTop: '8px',
                      borderTop: '1px solid var(--border-subtle)',
                      fontSize: '0.8rem',
                    }}
                  >
                    <div style={{ display: 'flex', alignItems: 'center', gap: '6px', color: '#6ee7b7' }}>
                      <MapPin size={13} />
                      <span style={{ fontWeight: 600 }}>{evt.venue}</span>
                    </div>

                    <div style={{ display: 'flex', alignItems: 'center', gap: '6px', color: 'var(--text-muted)' }}>
                      <CheckCircle2 size={13} color="#10b981" />
                      <span>Gymkhana Verified</span>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

'use client';



import React, { useState, useEffect, useEffectEvent } from 'react';

import { api } from '@/lib/api';

import { useToast } from '@/components/ui/Toast';

import { MessDayMenu } from '@/types/chat';

import {

  UtensilsCrossed,

  Coffee,

  Sun,

  Sunset,

  Moon,

  Calendar,

  AlertCircle,

  CheckCircle2,

  X,

  MapPin,

  Clock,

  Sparkles,

  FileText,

  Calculator,

  ChevronRight,

  Wrench,

} from 'lucide-react';



interface MessMenuDrawerProps {

  isOpen: boolean;

  onClose: () => void;

  defaultMessSlug?: string;

  onOpenTickets?: (messName: string) => void;

}



const MESSES = [

  { slug: 'pine-mess', name: 'Pine Mess', campus: 'North Campus', location: 'Near Alders (NDH 1)' },

  { slug: 'oak-mess', name: 'Oak Mess', campus: 'North Campus', location: 'North Dining Hall 2' },

  { slug: 'alder-mess', name: 'Alder Mess', campus: 'North Campus', location: 'Alder Hostel Cluster' },

  { slug: 'cedar-mess', name: 'Cedar Mess', campus: 'North Campus', location: 'Cedar Block Complex' },

  { slug: 'maple-mess', name: 'Maple Mess', campus: 'South Campus', location: 'South Dining Hall' },

];



const DAYS = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'] as const;



export const MessMenuDrawer: React.FC<MessMenuDrawerProps> = ({

  isOpen,

  onClose,

  defaultMessSlug = 'pine-mess',

  onOpenTickets,

}) => {

  const { error, success } = useToast();

  const [selectedMess, setSelectedMess] = useState<string>(defaultMessSlug);

  const [selectedDay, setSelectedDay] = useState<string>(() => new Date().toLocaleDateString('en-US', { weekday: 'long', timeZone: 'Asia/Kolkata' }));

  const [menu, setMenu] = useState<MessDayMenu | null>(null);

  const [loading, setLoading] = useState(true);

  const [activeTab, setActiveTab] = useState<'menu' | 'rebate'>('menu');



  // Rebate Form

  const [startDate, setStartDate] = useState('');

  const [endDate, setEndDate] = useState('');

  const [reason, setReason] = useState('Home Visit');

  const [rebateSubmitting, setRebateSubmitting] = useState(false);

  const [submittedRebates, setSubmittedRebates] = useState<

    Array<{ id: string; start: string; end: string; days: number; reason: string; status: string }>

  >([]);



  useEffect(() => {

    // Pick current day of week on mount

    const daysArr = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];

    const today = daysArr[new Date().getDay()];

    setSelectedDay(today);

  }, []);



  useEffect(() => {

    if (defaultMessSlug) {

      setSelectedMess(defaultMessSlug);

    }

  }, [defaultMessSlug]);



  useEffect(() => {

    if (isOpen) {

      loadMenu(selectedMess);

    }

  }, [isOpen, selectedMess]);



  const loadMenu = async (slug: string) => {

    setLoading(true);

    try {

      const res = await api.getMessMenu(slug);

      if (res.data) {

        setMenu(res.data);

      }

    } catch (err: unknown) {

      console.error('Failed to load menu:', err);

      error((err instanceof Error ? err.message : '') || 'Could not fetch mess menu');

    } finally {

      setLoading(false);

    }

  };
  const loadOnOpen = useEffectEvent(() => loadMenu(selectedMess));
  useEffect(() => { if (isOpen) loadOnOpen(); }, [isOpen, selectedMess]);



  const calculateRebateDays = () => {

    if (!startDate || !endDate) return 0;

    const s = new Date(startDate);

    const e = new Date(endDate);

    const diffTime = e.getTime() - s.getTime();

    if (diffTime < 0) return 0;

    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24)) + 1;

    return diffDays;

  };



  const handleApplyRebate = (e: React.FormEvent) => {

    e.preventDefault();

    const days = calculateRebateDays();

    if (days < 3) {

      error('Minimum 3 consecutive days are required to qualify for mess rebate.');

      return;

    }



    setRebateSubmitting(true);

    setTimeout(() => {

      setSubmittedRebates((prev) => [

        {

          id: `reb-${Date.now()}`,

          start: startDate,

          end: endDate,

          days,

          reason,

          status: 'Local draft — not submitted',

        },

        ...prev,

      ]);

      setRebateSubmitting(false);

      setStartDate('');

      setEndDate('');

      success('Draft saved for this visit. Submit your request through the official mess office.');

    }, 600);

  };



  if (!isOpen) return null;



  const currentMessObj = MESSES.find((m) => m.slug === selectedMess) || MESSES[0];



  return (

    <div className="fixed inset-0 z-50 flex items-center justify-end bg-black/60 backdrop-blur-sm animate-fade-in">

      <div className="w-full max-w-2xl h-full bg-[var(--bg-secondary)] border-l border-[var(--border-subtle)] shadow-2xl flex flex-col transform transition-transform duration-300">

        {/* Drawer Header */}

        <div className="p-6 border-b border-[var(--border-subtle)] flex items-center justify-between bg-[var(--bg-secondary)]">

          <div className="flex items-center gap-3">

            <div className="p-2.5 rounded-xl bg-amber-500/10 text-[var(--accent)] border border-amber-500/20 shadow-inner">

              <UtensilsCrossed size={24} />

            </div>

            <div>

              <div className="flex items-center gap-2">

                <h2 className="text-xl font-bold text-[var(--text-primary)] tracking-tight">Mess Menu &amp; Rebate</h2>

                <span className="px-2 py-0.5 text-xs font-semibold bg-amber-500/10 text-[var(--accent)] border border-amber-500/20 rounded">

                  {currentMessObj.campus}

                </span>

              </div>

              <p className="text-xs text-[var(--text-secondary)] flex items-center gap-1.5 mt-0.5">

                <MapPin size={12} className="text-[var(--accent)]/80" />

                {currentMessObj.name} &bull; {currentMessObj.location}

              </p>

            </div>

          </div>



          <div className="flex items-center gap-2">

            <button

              onClick={onClose}

              className="p-2 rounded-lg text-[var(--text-secondary)] hover:text-[var(--text-primary)] hover:bg-white/5 transition-colors"

            >

              <X size={20} />

            </button>

          </div>

        </div>



        {/* Mess Selector & Navigation Bar */}

        <div className="p-4 border-b border-[var(--border-subtle)] bg-[var(--bg-secondary)] space-y-3">

          <div className="flex items-center justify-between gap-3 flex-wrap">

            <div className="flex items-center gap-2">

              <label htmlFor="mess-select" className="text-xs font-semibold text-[var(--text-secondary)] uppercase tracking-wider">

                Dining Hall:

              </label>

              <select

                id="mess-select"

                value={selectedMess}

                onChange={(e) => setSelectedMess(e.target.value)}

                className="bg-[var(--bg-secondary)] border border-[var(--border-subtle)] text-[var(--text-primary)] rounded-lg px-3 py-1.5 text-sm focus:outline-none focus:border-amber-500"

              >

                {MESSES.map((m) => (

                  <option key={m.slug} value={m.slug}>

                    {m.name} ({m.campus})

                  </option>

                ))}

              </select>

            </div>



            {/* Sub-tabs: Menu vs Rebates */}

            <div className="flex items-center gap-1 bg-[var(--bg-secondary)] p-1 rounded-lg border border-[var(--border-subtle)] text-xs">

              <button

                onClick={() => setActiveTab('menu')}

                className={`px-3 py-1.5 rounded-md font-medium transition-all flex items-center gap-1.5 ${

                  activeTab === 'menu'

                    ? 'bg-[var(--accent)] text-[var(--on-accent)] text-[var(--text-primary)] shadow-sm'

                    : 'text-[var(--text-secondary)] hover:text-[var(--text-primary)]'

                }`}

              >

                <UtensilsCrossed size={12} /> Today&apos;s Menu

              </button>

              <button

                onClick={() => setActiveTab('rebate')}

                className={`px-3 py-1.5 rounded-md font-medium transition-all flex items-center gap-1.5 ${

                  activeTab === 'rebate'

                    ? 'bg-[var(--accent)] text-[var(--on-accent)] text-[var(--text-primary)] shadow-sm'

                    : 'text-[var(--text-secondary)] hover:text-[var(--text-primary)]'

                }`}

              >

                <Calculator size={12} /> Rebate draft

              </button>

            </div>

          </div>

        </div>



        {/* Tab 1: Menu View */}

        {activeTab === 'menu' && (

          <div className="flex-1 overflow-y-auto flex flex-col">

            {/* Days of Week Filter */}

            <div className="px-6 py-3 border-b border-[var(--border-subtle)] bg-[var(--bg-secondary)] flex items-center gap-2 overflow-x-auto">

              {DAYS.map((d) => (

                <button

                  key={d}

                  onClick={() => setSelectedDay(d)}

                  className={`px-3 py-1 rounded-md text-xs font-medium whitespace-nowrap transition-all ${

                    selectedDay === d

                      ? 'bg-amber-500/20 text-[var(--accent)] border border-amber-500/40 shadow-sm'

                      : 'text-[var(--text-secondary)] hover:text-[var(--text-secondary)]'

                  }`}

                >

                  {d}

                </button>

              ))}

            </div>



            {/* Menu Sections */}

            <div className="p-6 space-y-4 flex-1">

              {loading ? (

                <div className="flex flex-col items-center justify-center h-64 text-[var(--text-secondary)] gap-3">

                  <div className="w-8 h-8 border-2 border-amber-400 border-t-transparent rounded-full animate-spin" />

                  <p className="text-sm">Fetching daily dining schedule...</p>

                </div>

              ) : (

                <div className="grid grid-cols-1 gap-4">

                  {/* Breakfast */}

                  <div className="bg-[var(--bg-secondary)] border border-[var(--border-subtle)] rounded-xl p-4.5 hover:border-amber-500/30 transition-all">

                    <div className="flex items-center justify-between pb-3 mb-3 border-b border-[var(--border-subtle)]">

                      <div className="flex items-center gap-2.5">

                        <div className="p-2 rounded-lg bg-orange-500/10 text-[var(--accent)]">

                          <Coffee size={18} />

                        </div>

                        <div>

                          <h4 className="text-sm font-bold text-[var(--text-primary)]">Breakfast</h4>

                          <span className="text-[11px] text-[var(--text-secondary)]">7:30 AM &ndash; 9:30 AM</span>

                        </div>

                      </div>

                      <span className="text-xs px-2 py-0.5 rounded bg-white/5 text-[var(--text-secondary)]">Morning</span>

                    </div>

                    <p className="text-sm text-[var(--text-secondary)] leading-relaxed font-medium">

                      {menu?.breakfast || 'Idli, Sambhar, Coconut Chutney, Bread Butter, Sprouts, Milk / Tea'}

                    </p>

                  </div>



                  {/* Lunch */}

                  <div className="bg-[var(--bg-secondary)] border border-[var(--border-subtle)] rounded-xl p-4.5 hover:border-amber-500/30 transition-all">

                    <div className="flex items-center justify-between pb-3 mb-3 border-b border-[var(--border-subtle)]">

                      <div className="flex items-center gap-2.5">

                        <div className="p-2 rounded-lg bg-yellow-500/10 text-yellow-400">

                          <Sun size={18} />

                        </div>

                        <div>

                          <h4 className="text-sm font-bold text-[var(--text-primary)]">Lunch</h4>

                          <span className="text-[11px] text-[var(--text-secondary)]">12:30 PM &ndash; 2:30 PM</span>

                        </div>

                      </div>

                      <span className="text-xs px-2 py-0.5 rounded bg-white/5 text-[var(--text-secondary)]">Afternoon</span>

                    </div>

                    <p className="text-sm text-[var(--text-secondary)] leading-relaxed font-medium">

                      {menu?.lunch || 'Rajma Masala, Steamed Jeera Rice, Phulka, Boondi Raita, Green Salad'}

                    </p>

                  </div>



                  {/* Evening Snacks */}

                  <div className="bg-[var(--bg-secondary)] border border-[var(--border-subtle)] rounded-xl p-4.5 hover:border-amber-500/30 transition-all">

                    <div className="flex items-center justify-between pb-3 mb-3 border-b border-[var(--border-subtle)]">

                      <div className="flex items-center gap-2.5">

                        <div className="p-2 rounded-lg bg-amber-500/10 text-[var(--accent)]">

                          <Sunset size={18} />

                        </div>

                        <div>

                          <h4 className="text-sm font-bold text-[var(--text-primary)]">Evening Snacks</h4>

                          <span className="text-[11px] text-[var(--text-secondary)]">5:00 PM &ndash; 6:00 PM</span>

                        </div>

                      </div>

                      <span className="text-xs px-2 py-0.5 rounded bg-white/5 text-[var(--text-secondary)]">Evening</span>

                    </div>

                    <p className="text-sm text-[var(--text-secondary)] leading-relaxed font-medium">

                      {menu?.snacks || 'Hot Samosa with Mint Chutney, Biscuits, Hot Tea / Coffee'}

                    </p>

                  </div>



                  {/* Dinner */}

                  <div className="bg-[var(--bg-secondary)] border border-[var(--border-subtle)] rounded-xl p-4.5 hover:border-amber-500/30 transition-all">

                    <div className="flex items-center justify-between pb-3 mb-3 border-b border-[var(--border-subtle)]">

                      <div className="flex items-center gap-2.5">

                        <div className="p-2 rounded-lg bg-indigo-500/10 text-[var(--accent)]">

                          <Moon size={18} />

                        </div>

                        <div>

                          <h4 className="text-sm font-bold text-[var(--text-primary)]">Dinner</h4>

                          <span className="text-[11px] text-[var(--text-secondary)]">7:30 PM &ndash; 9:30 PM</span>

                        </div>

                      </div>

                      <span className="text-xs px-2 py-0.5 rounded bg-white/5 text-[var(--text-secondary)]">Night</span>

                    </div>

                    <p className="text-sm text-[var(--text-secondary)] leading-relaxed font-medium">

                      {menu?.dinner || 'Paneer Butter Masala, Dal Makhani, Tawa Roti, Rice, Gulab Jamun (Sweet)'}

                    </p>

                  </div>

                </div>

              )}



              {/* Action row to file Mess Tickets */}

              <div className="pt-2">

                <div className="p-4 rounded-xl bg-amber-500/5 border border-amber-500/20 flex items-center justify-between gap-4">

                  <div>

                    <h5 className="text-xs font-bold text-[var(--text-primary)]">Notice an issue with food quality or menu shortage?</h5>

                    <p className="text-[11px] text-[var(--text-secondary)] mt-0.5">

                      File a ticket for the Mess Warden and Dining Committee to review directly.

                    </p>

                  </div>

                  {onOpenTickets && (

                    <button

                      onClick={() => onOpenTickets(currentMessObj.name)}

                      className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-semibold bg-[var(--accent)] text-[var(--on-accent)] hover:bg-[var(--accent)] text-[var(--on-accent)] text-[var(--text-primary)] transition-all shadow-md whitespace-nowrap"

                    >

                      <Wrench size={12} />

                      Report Mess Issue

                    </button>

                  )}

                </div>

              </div>

            </div>

          </div>

        )}



        {/* Tab 2: Rebate View */}

        {activeTab === 'rebate' && (

          <div className="flex-1 overflow-y-auto p-6 space-y-6">

            {/* Policy Info Card */}

            <div className="p-4 rounded-xl bg-[var(--bg-secondary)] border border-[var(--border-subtle)] space-y-2">

              <div className="flex items-center gap-2 text-[var(--accent)] font-bold text-sm">

                <AlertCircle size={16} />

                <span>IIT Mandi Mess Rebate Guidelines</span>

              </div>

              <ul className="text-xs text-[var(--text-secondary)] space-y-1 list-disc list-inside">

                <li>Minimum rebate duration is <strong className="text-[var(--text-primary)]">3 consecutive days</strong>.</li>

                <li>Applications must be submitted at least <strong className="text-[var(--text-primary)]">48 hours in advance</strong>.</li>

                <li>Rebate amount is calculated @ â‚¹140/day and credited directly to the next semester mess billing ledger.</li>

              </ul>

            </div>



            {/* Application Form */}

            <form onSubmit={handleApplyRebate} className="bg-[var(--bg-secondary)] border border-[var(--border-subtle)] rounded-xl p-5 space-y-4">

              <h4 className="text-sm font-bold text-[var(--text-primary)] flex items-center gap-2">

                <Calendar size={16} className="text-[var(--accent)]" />

                Apply for Mess Rebate

              </h4>



              <div className="grid grid-cols-2 gap-3">

                <div>

                  <label htmlFor="rebate-from-date" className="block text-xs font-medium text-[var(--text-secondary)] mb-1">From Date</label>

                  <input

                    id="rebate-from-date"

                    type="date"

                    required

                    value={startDate}

                    onChange={(e) => setStartDate(e.target.value)}

                    className="w-full bg-[var(--bg-secondary)] border border-[var(--border-subtle)] rounded-lg px-3 py-2 text-xs text-[var(--text-primary)] focus:outline-none focus:border-amber-500"

                  />

                </div>

                <div>

                  <label htmlFor="rebate-to-date" className="block text-xs font-medium text-[var(--text-secondary)] mb-1">To Date</label>

                  <input

                    id="rebate-to-date"

                    type="date"

                    required

                    value={endDate}

                    onChange={(e) => setEndDate(e.target.value)}

                    className="w-full bg-[var(--bg-secondary)] border border-[var(--border-subtle)] rounded-lg px-3 py-2 text-xs text-[var(--text-primary)] focus:outline-none focus:border-amber-500"

                  />

                </div>

              </div>



              <div>

                <label htmlFor="rebate-reason" className="block text-xs font-medium text-[var(--text-secondary)] mb-1">Reason for Leave</label>

                <select

                  id="rebate-reason"

                  value={reason}

                  onChange={(e) => setReason(e.target.value)}

                  className="w-full bg-[var(--bg-secondary)] border border-[var(--border-subtle)] rounded-lg px-3 py-2 text-xs text-[var(--text-primary)] focus:outline-none focus:border-amber-500"

                >

                  <option value="Home Visit">Home Visit / Personal Leave</option>

                  <option value="Academic Conference / Fest">Academic Conference / Inter-IIT Fest</option>

                  <option value="Medical Leave">Medical Leave (Approved by Medical Officer)</option>

                  <option value="Internship / Project Work">Official Internship / Project Work</option>

                </select>

              </div>



              {calculateRebateDays() > 0 && (

                <div className="p-3 rounded-lg bg-amber-500/10 border border-amber-500/20 text-xs text-[var(--accent)] flex items-center justify-between">

                  <span>Total Duration: <strong>{calculateRebateDays()} days</strong></span>

                  <span>Est. Credit: <strong>â‚¹{calculateRebateDays() * 140}</strong></span>

                </div>

              )}



              <button

                type="submit"

                disabled={rebateSubmitting}

                className="w-full py-2.5 rounded-lg bg-gradient-to-r from-amber-600 to-orange-600 hover:from-amber-500 hover:to-orange-500 text-[var(--text-primary)] text-xs font-bold transition-all shadow-md disabled:opacity-50"

              >

                {rebateSubmitting ? 'Submitting Application...' : 'Submit Rebate Request'}

              </button>

            </form>



            {/* Submitted Applications List */}

            <div className="space-y-3">

              <h5 className="text-xs font-bold uppercase tracking-wider text-[var(--text-secondary)]">Your Recent Rebates</h5>

              {submittedRebates.map((reb) => (

                <div

                  key={reb.id}

                  className="p-3.5 rounded-xl bg-[var(--bg-secondary)] border border-[var(--border-subtle)] flex items-center justify-between gap-3 text-xs"

                >

                  <div>

                    <div className="flex items-center gap-2">

                      <span className="font-semibold text-[var(--text-primary)]">{reb.reason}</span>

                      <span className="text-[11px] text-[var(--accent)] font-mono">({reb.days} days)</span>

                    </div>

                    <div className="text-[11px] text-[var(--text-secondary)] mt-0.5">

                      {reb.start} &rarr; {reb.end}

                    </div>

                  </div>

                  <span className="px-2 py-0.5 rounded text-[11px] font-semibold bg-emerald-500/10 text-[var(--accent)] border border-emerald-500/20">

                    {reb.status}

                  </span>

                </div>

              ))}

            </div>

          </div>

        )}



        {/* Footer */}

        <div className="p-4 border-t border-[var(--border-subtle)] bg-[var(--bg-secondary)] flex items-center justify-between text-xs text-[var(--text-secondary)]">

          <span>IIT Mandi Dining Affairs Council (DAC)</span>

          <span className="text-[var(--accent)]/80 font-medium">Rebate Sync Active</span>

        </div>

      </div>

    </div>

  );

};

