            onClick={onOpenInfo}
            className="btn-icon btn-ghost"
            title="Channel info & members"
          >
            <Info size={18} />
          </button>
        )}
      </div>
    </div>
  );
};

'use client';

import React, { useState, useEffect } from 'react';
import { Message, ConversationMember, Attachment } from '@/types/chat';
import { Avatar } from '@/components/ui/Avatar';
import { formatTime, formatFileSize, getMemberProfile } from '@/lib/utils';
import { api } from '@/lib/api';
import { useToast } from '@/components/ui/Toast';
import {
  Smile,
  Edit2,
  Trash2,
  Check,
  CheckCheck,
  FileText,
  Download,
  Play,
  X,
  Save,
} from 'lucide-react';

interface MessageItemProps {
  message: Message;
  currentUserId: string;
  members: ConversationMember[];
  onToggleReaction: (messageId: string, emoji: string) => void;
  onEditMessage: (messageId: string, body: string) => Promise<void>;
  onDeleteMessage: (messageId: string) => Promise<void>;
}

const QUICK_EMOJIS = ['👍', '❤️', '🔥', '😂', '🎉', '🚀'];

export const MessageItem: React.FC<MessageItemProps> = ({
  message,
  currentUserId,
  members,
  onToggleReaction,
  onEditMessage,
  onDeleteMessage,
}) => {
  const { error } = useToast();
  const isMe = message.sender_id === currentUserId;
  const isDeleted = !!message.deleted_at;

  const [isEditing, setIsEditing] = useState(false);
  const [editBody, setEditBody] = useState(message.body);
  const [isSavingEdit, setIsSavingEdit] = useState(false);

  const [signedUrls, setSignedUrls] = useState<Record<string, string>>({});
  const [loadingUrls, setLoadingUrls] = useState<Record<string, boolean>>({});

  // Sender profile
  const senderMember = members.find((m) => m.user_id === message.sender_id);
  const senderProfile = getMemberProfile(senderMember);
  const senderName =
    senderProfile?.display_name ||
    senderProfile?.username ||
    'Student';
  const senderAvatar = senderProfile?.avatar_key;

  // Determine read status: did any other active member read past this message's seq?
  const isReadByOthers = members.some(
    (m) => m.user_id !== currentUserId && !m.left_at && m.last_read_seq >= message.seq
  );

  // Load signed URLs for attachments
  const fetchAttachmentUrl = async (attachment: Attachment) => {
    if (signedUrls[attachment.id] || loadingUrls[attachment.id]) return;

    setLoadingUrls((prev) => ({ ...prev, [attachment.id]: true }));
    try {
      const res = await api.getAttachmentUrl(attachment.id);
      if (res.data?.signedUrl) {
        setSignedUrls((prev) => ({ ...prev, [attachment.id]: res.data.signedUrl }));
      }
    } catch (err: unknown) {
      console.error('Failed to get attachment URL:', err);
    } finally {
      setLoadingUrls((prev) => ({ ...prev, [attachment.id]: false }));
    }
  };

  useEffect(() => {
    let active = true;
    if (!isDeleted) {
      for (const attachment of message.attachments || []) {
        if (!/^(image|audio)\//.test(attachment.mime_type)) continue;
        api.getAttachmentUrl(attachment.id).then(res => {
          if (active && res.data?.signedUrl) setSignedUrls(previous => ({ ...previous, [attachment.id]: res.data.signedUrl }));
        }).catch(() => {});
      }
    }
    return () => { active = false; };
  }, [message.attachments, isDeleted]);

  // Aggregate reactions: emoji -> { count, hasReacted }
  const reactionGroups: { emoji: string; count: number; hasReacted: boolean }[] = [];
  if (message.message_reactions && message.message_reactions.length > 0) {
    const map = new Map<string, { count: number; hasReacted: boolean }>();
    for (const r of message.message_reactions) {
      const existing = map.get(r.emoji) || { count: 0, hasReacted: false };
      existing.count += 1;
      if (r.user_id === currentUserId) {
        existing.hasReacted = true;
      }
      map.set(r.emoji, existing);
    }
    map.forEach((val, emoji) => {
      reactionGroups.push({ emoji, count: val.count, hasReacted: val.hasReacted });
    });
  }

  const handleSaveEdit = async () => {
    if (!editBody.trim()) {
      error('Message text cannot be empty');
      return;
    }
    setIsSavingEdit(true);
    try {
      await onEditMessage(message.id, editBody.trim());
      setIsEditing(false);
    } catch (err: unknown) {
      error((err instanceof Error ? err.message : '') || 'Failed to edit message');
    } finally {
      setIsSavingEdit(false);
    }
  };

  const handleDelete = async () => {
    if (confirm('Are you sure you want to delete this message?')) {
      try {
        await onDeleteMessage(message.id);
      } catch (err: unknown) {
        error((err instanceof Error ? err.message : '') || 'Failed to delete message');
      }
    }
  };

  return (
    <div className={`message-row ${isMe ? 'sent' : 'received'}`}>
      {!isMe && (
        <Avatar name={senderName} src={senderAvatar} size="sm" />
      )}

      <div style={{ maxWidth: '100%' }}>
        <div className={`message-bubble ${isDeleted ? 'deleted' : ''}`}>
          {/* Sender name for received messages in group chats */}
          {!isMe && (
            <div className="message-sender-name">{senderName}</div>
          )}

          {/* Deleted tombstone */}
          {isDeleted ? (
            <div className="message-text">This message was deleted</div>
          ) : isEditing ? (
            <div style={{ minWidth: '220px' }}>
              <textarea
                value={editBody}
                onChange={(e) => setEditBody(e.target.value)}
                className="composer-input"
                style={{
                  width: '100%',
                  background: 'rgba(0, 0, 0, 0.3)',
                  border: '1px solid var(--border-medium)',
                  borderRadius: 'var(--radius-sm)',
                  padding: '6px 8px',
                  color: 'white',
                }}
                rows={2}
              />
              <div style={{ display: 'flex', gap: '6px', justifyContent: 'flex-end', marginTop: '6px' }}>
                <button
                  onClick={() => setIsEditing(false)}
                  className="btn btn-ghost"
                  style={{ padding: '4px 8px', fontSize: '0.8rem' }}
                >
                  <X size={12} />
                  Cancel
                </button>
                <button
                  onClick={handleSaveEdit}
                  disabled={isSavingEdit}
                  className="btn btn-primary"
                  style={{ padding: '4px 10px', fontSize: '0.8rem' }}
                >
                  <Save size={12} />
                  {isSavingEdit ? 'Saving...' : 'Save'}
                </button>
              </div>
            </div>
          ) : (
            <>
              {/* Message text */}
              {message.body && (
                <div className="message-text">{message.body}</div>
              )}

              {/* Attachments */}
              {message.attachments && message.attachments.length > 0 && (
                <div style={{ display: 'flex', flexDirection: 'column', gap: '6px', marginTop: '4px' }}>
                  {message.attachments.map((att) => {
                    const isImage = att.mime_type.startsWith('image/');
                    const isAudio = att.mime_type.startsWith('audio/');
                    const url = signedUrls[att.id];

                    if (isImage) {
                      return (
                        <div key={att.id} style={{ position: 'relative' }}>
                          {url ? (
                            <a href={url} target="_blank" rel="noopener noreferrer">
                              <img
                                src={url}
                                alt={att.original_name}
                                className="attachment-img-preview"
                              />
                            </a>
                          ) : (
                            <div
                              onClick={() => fetchAttachmentUrl(att)}
                              className="attachment-card"
                            >
                              <FileText size={18} color="var(--accent)" />
                              <span>{att.original_name} (Click to load image)</span>
                            </div>
                          )}
                        </div>
                      );
                    }

                    if (isAudio && url) {
                      return (
                        <div key={att.id} style={{ marginTop: '4px' }}>
                          <audio controls src={url} style={{ maxWidth: '240px', height: '36px' }} />
                        </div>
                      );
                    }

                    return (
                      <div
                        key={att.id}
                        onClick={async () => {
                          if (url) {
                            window.open(url, '_blank');
                          } else {
                            await fetchAttachmentUrl(att);
                          }
                        }}
                        className="attachment-card"
                      >
                        <FileText size={18} color="var(--accent)" style={{ flexShrink: 0 }} />
                        <div style={{ flex: 1, minWidth: 0 }}>
                          <div style={{ fontSize: '0.833rem', fontWeight: 600, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                            {att.original_name}
                          </div>
                          <div style={{ fontSize: '0.8rem', color: 'var(--text-muted)' }}>
                            {formatFileSize(att.size_bytes)}
                          </div>
                        </div>
                        <Download size={14} color="#94a3b8" />
                      </div>
                    );
                  })}
                </div>
              )}
            </>
          )}

          {/* Message Meta (time, edited, read checkmarks) */}
          <div className="message-meta">
            {message.edited_at && !isDeleted && (
              <span className="message-edited-tag">edited</span>
            )}
            <span>{formatTime(message.created_at)}</span>
            {isMe && !isDeleted && (
              <span title={isReadByOthers ? 'Read' : 'Sent'}>
                {isReadByOthers ? (
                  <CheckCheck size={13} color="var(--accent)" />
                ) : (
                  <Check size={13} color="rgba(255,255,255,0.7)" />
                )}
              </span>
            )}
          </div>
        </div>

        {/* Hover Action Menu */}
        {!isDeleted && (
          <div className="message-hover-actions">
            {QUICK_EMOJIS.map((emoji) => (
              <button
                key={emoji}
                onClick={() => onToggleReaction(message.id, emoji)}
                className="action-btn-mini"
                title={`React with ${emoji}`}
              >
                {emoji}
              </button>
            ))}

            {isMe && (
              <>
                <button
                  onClick={() => {
                    setEditBody(message.body);
                    setIsEditing(true);
                  }}
                  className="action-btn-mini"
                  title="Edit message"
                >
                  <Edit2 size={13} />
                </button>
                <button
                  onClick={handleDelete}
                  className="action-btn-mini"
                  style={{ color: 'var(--danger)' }}
                  title="Delete message"
                >
                  <Trash2 size={13} />
                </button>
              </>
            )}
          </div>
        )}

        {/* Reaction Badges */}
        {reactionGroups.length > 0 && !isDeleted && (
          <div className="reactions-row">
            {reactionGroups.map((rg) => (
              <button
                key={rg.emoji}
                onClick={() => onToggleReaction(message.id, rg.emoji)}
                className={`reaction-pill ${rg.hasReacted ? 'active' : ''}`}
                title={`Reacted by ${rg.count} user(s)`}
              >
                <span>{rg.emoji}</span>
                <span className="reaction-count">{rg.count}</span>
              </button>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

'use client';

import React, { useState, useEffect } from 'react';
import { Modal } from '@/components/ui/Modal';
import { api } from '@/lib/api';
import { Message, ConversationMember } from '@/types/chat';
import { Search, FileText } from 'lucide-react';
import { formatTime, formatDateDivider } from '@/lib/utils';

interface MessageSearchModalProps {
  isOpen: boolean;
  onClose: () => void;
  conversationId: string;
  members: ConversationMember[];
}

export const MessageSearchModal: React.FC<MessageSearchModalProps> = ({
  isOpen,
  onClose,
  conversationId,
  members,
}) => {
  const [query, setQuery] = useState('');
  const [results, setResults] = useState<Message[]>([]);
  const [isSearching, setIsSearching] = useState(false);
  const [searchError, setSearchError] = useState('');

  useEffect(() => {
    if (!isOpen || !query.trim()) {
      return;
    }

    let active = true;
    const timer = setTimeout(async () => {
      setIsSearching(true);
      try {
        const res = await api.searchMessages(conversationId, query.trim());
        if (active && res.data) {
          setResults(res.data);
        }
      } catch (err: unknown) {
        if (active) setSearchError(err instanceof Error ? err.message : 'Search failed. Try again.');
      } finally {
        if (active) setIsSearching(false);
      }
    }, 300);

    return () => { active = false; clearTimeout(timer); };
  }, [query, isOpen, conversationId]);

  return (
    <Modal
      isOpen={isOpen}
      onClose={onClose}
      title="Search Messages"
      description="Search within this conversation's history"
      maxWidth={520}
    >
      <div>
        <div className="search-box" style={{ marginBottom: '16px' }}>
          <Search size={16} className="search-icon" />
          <input
            type="text"
            placeholder="Type words to search..."
            className="search-input"
            value={query}
            aria-label="Search messages"
            onChange={(e) => { setQuery(e.target.value); setResults([]); setSearchError(''); setIsSearching(!!e.target.value.trim()); }}
            autoFocus
          />
        </div>

        <div style={{ maxHeight: '320px', overflowY: 'auto', display: 'flex', flexDirection: 'column', gap: '8px' }}>
          {isSearching ? (
            <div style={{ padding: '24px', textAlign: 'center', color: 'var(--text-muted)' }}>
              Searching history...
            </div>
          ) : results.length === 0 ? (
            <div style={{ padding: '24px', textAlign: 'center', color: 'var(--text-muted)' }}>
              {searchError || (query ? 'No matching messages found.' : 'Enter search terms above.')}
            </div>
          ) : (
            results.map((msg) => {
              const sender = members.find((m) => m.user_id === msg.sender_id);
              const senderName =
                sender?.profiles?.display_name ||
                sender?.profiles?.username ||
                'User';

              return (
                <div
                  key={msg.id}
                  style={{
                    padding: '10px 14px',
                    borderRadius: 'var(--radius-md)',
                    background: 'var(--border-subtle)',
                    border: '1px solid var(--border-subtle)',
                    display: 'flex',
                    flexDirection: 'column',
                    gap: '4px',
                  }}
                >
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                    <span style={{ fontSize: '0.8rem', fontWeight: 700, color: 'var(--accent)' }}>
                      {senderName}
                    </span>
                    <span style={{ fontSize: '0.8rem', color: 'var(--text-muted)' }}>
                      {formatDateDivider(msg.created_at)} at {formatTime(msg.created_at)}
                    </span>
                  </div>
                  <div style={{ fontSize: '0.9rem', color: 'var(--text-primary)', whiteSpace: 'pre-wrap' }}>
                    {msg.body}
                  </div>
                </div>
              );
            })
          )}
        </div>
      </div>
    </Modal>
  );
};

'use client';

import React, { useState, useEffect } from 'react';
import { Modal } from '@/components/ui/Modal';
import { Avatar } from '@/components/ui/Avatar';
import { Badge } from '@/components/ui/Badge';
import { useChat } from '@/context/ChatContext';
import { useAuth } from '@/context/AuthContext';
import { useToast } from '@/components/ui/Toast';
import { api } from '@/lib/api';
import { Profile } from '@/types/chat';
import {
  Users,
  Edit2,
  Check,
  UserPlus,
  UserMinus,
  LogOut,
  Crown,
  Search,
  ShieldCheck,
} from 'lucide-react';
import { ALL_CAMPUS_ROOMS, isCampusRoomAdmin } from '@/lib/campus-rooms';

interface GroupInfoDrawerProps {
  isOpen: boolean;
  onClose: () => void;
}

export const GroupInfoDrawer: React.FC<GroupInfoDrawerProps> = ({
  isOpen,
  onClose,
}) => {
  const {
    activeConversation,
    renameGroup,
    addMemberToGroup,
    leaveOrRemoveMember,
  } = useChat();
  const { user, profile } = useAuth();
  const { success, error } = useToast();

  const [isEditingTitle, setIsEditingTitle] = useState(false);
  const [newTitle, setNewTitle] = useState(activeConversation?.title || '');
  const [isAddingMember, setIsAddingMember] = useState(false);

  // Add member search state
  const [memberSearchQuery, setMemberSearchQuery] = useState('');
  const [candidateUsers, setCandidateUsers] = useState<Profile[]>([]);
  const [isSearchingCandidates, setIsSearchingCandidates] = useState(false);



  // Search candidate users to add
  useEffect(() => {
    if (!isAddingMember) return;

    let active = true;
    const timer = setTimeout(async () => {
      setIsSearchingCandidates(true);
      try {
        const res = await api.searchUsers(memberSearchQuery);
        if (active && res.data) {
          // Filter out users already in active members
          const existingIds = new Set(
            activeConversation?.conversation_members
              ?.filter((m) => !m.left_at)
              .map((m) => m.user_id) || []
          );
          setCandidateUsers(res.data.filter((u) => !existingIds.has(u.id)));
        }
      } catch (err: unknown) {
        console.error('Candidate search failed:', err);
      } finally {
        if (active) setIsSearchingCandidates(false);
      }
    }, 250);

    return () => { active = false; clearTimeout(timer); };
  }, [memberSearchQuery, isAddingMember, activeConversation]);

  if (!activeConversation) return null;

  const currentMember = activeConversation.conversation_members?.find(
    (m) => m.user_id === user?.id
  );
  const isOwner = currentMember?.role === 'owner';

  // Identify campus room
  const normalizedTitle = (activeConversation.title || '').replace(/^#/, '').toLowerCase().trim();
  const campusRoom = ALL_CAMPUS_ROOMS.find(
    (r) =>
      r.name.toLowerCase() === normalizedTitle ||
      r.slug.toLowerCase() === normalizedTitle ||
      (r.courseCode && normalizedTitle.includes(r.courseCode.toLowerCase()))
  );

  const isCampusAdmin = campusRoom
    ? isCampusRoomAdmin(campusRoom.slug, user) ||
      isCampusRoomAdmin(campusRoom.slug, profile?.username)
    : false;
  const isPrivileged = Boolean(isOwner || isCampusAdmin);

  const activeMembers =
    activeConversation.conversation_members?.filter((m) => !m.left_at) || [];

  const handleSaveTitle = async () => {
    if (!newTitle.trim()) {
      error('Title cannot be empty');
      return;
    }
    try {
      await renameGroup(newTitle.trim());
      setIsEditingTitle(false);
      success('Group renamed');
    } catch (err: unknown) {
      error((err instanceof Error ? err.message : '') || 'Failed to rename group');
    }
  };

  const handleAddMember = async (userId: string) => {
    try {
      await addMemberToGroup(userId);
      success('Member added to group');
      setIsAddingMember(false);
      setMemberSearchQuery('');
    } catch (err: unknown) {
      error((err instanceof Error ? err.message : '') || 'Failed to add member');
    }
  };

  const handleRemoveMember = async (userId: string, memberName: string) => {
    const isSelf = userId === user?.id;
    const confirmMsg = isSelf
      ? 'Are you sure you want to leave this group?'
      : `Remove ${memberName} from this group?`;

    if (confirm(confirmMsg)) {
      try {
        await leaveOrRemoveMember(userId);
        success(isSelf ? 'You left the group' : `${memberName} removed`);
        if (isSelf) {
          onClose();
        }
      } catch (err: unknown) {
        error((err instanceof Error ? err.message : '') || 'Action failed');
      }
    }
  };

  return (
    <Modal
      isOpen={isOpen}
      onClose={onClose}
      title="Group Information"
      description={`${activeMembers.length} active participants`}
      maxWidth={480}
    >
      <div>
        {/* Title & Rename */}
        <div
          style={{
            padding: '16px',
            background: 'rgba(0, 0, 0, 0.2)',
            borderRadius: 'var(--radius-lg)',
            border: '1px solid var(--border-subtle)',
            marginBottom: '20px',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'space-between',
            gap: '12px',
          }}
        >
          {isEditingTitle ? (
            <div style={{ display: 'flex', gap: '8px', width: '100%' }}>
              <input
                type="text"
                className="input-control"
                value={newTitle}
                onChange={(e) => setNewTitle(e.target.value)}
                maxLength={120}
              />
              <button
                type="button"
                onClick={handleSaveTitle}
                className="btn btn-primary"
                style={{ padding: '8px 12px' }}
              >
                <Check size={16} />
              </button>
            </div>
          ) : (
            <>
              <div>
                <h3 style={{ fontSize: '1.067rem', fontWeight: 700 }}>
                  {activeConversation.title || 'Group Chat'}
                </h3>
                <span style={{ fontSize: '0.8rem', color: 'var(--text-muted)' }}>
                  Created on{' '}
                  {new Date(activeConversation.created_at).toLocaleDateString()}
                </span>
              </div>
              {isPrivileged && (
                <button
                  type="button"
                  onClick={() => setIsEditingTitle(true)}
                  className="btn-icon btn-ghost"
                  title="Rename Group"
                >
                  <Edit2 size={16} />
                </button>
              )}
            </>
          )}
        </div>

        {/* Member Action: Add Member button (Owner/Admin) */}
        {isPrivileged && (
          <div style={{ marginBottom: '16px' }}>
            {!isAddingMember ? (
              <button
                type="button"
                onClick={() => setIsAddingMember(true)}
                className="btn btn-secondary"
                style={{ width: '100%', padding: '9px' }}
              >
                <UserPlus size={16} />
                Add Member
              </button>
            ) : (
              <div
                style={{
                  padding: '12px',
                  background: 'var(--accent-light)',
                  borderRadius: 'var(--radius-md)',
                  border: '1px solid var(--accent-light)',
                }}
              >
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '8px' }}>
                  <span style={{ fontSize: '0.8rem', fontWeight: 600, color: 'var(--accent)' }}>
                    Find user to add:
                  </span>
                  <button
                    onClick={() => setIsAddingMember(false)}
                    style={{ background: 'transparent', border: 'none', color: 'var(--text-muted)', cursor: 'pointer', fontSize: '0.8rem' }}
                  >
                    Cancel
                  </button>
                </div>

                <div className="search-box" style={{ marginBottom: '8px' }}>
                  <Search size={14} className="search-icon" />
                  <input
                    type="text"
                    placeholder="Search by username..."
                    className="search-input"
                    value={memberSearchQuery}
                    onChange={(e) => setMemberSearchQuery(e.target.value)}
                    autoFocus
                  />
                </div>

                <div style={{ maxHeight: '160px', overflowY: 'auto', display: 'flex', flexDirection: 'column', gap: '4px' }}>
                  {isSearchingCandidates ? (
                    <div style={{ fontSize: '0.8rem', textAlign: 'center', padding: '12px', color: 'var(--text-muted)' }}>
                      Searching...
                    </div>
                  ) : candidateUsers.length === 0 ? (
                    <div style={{ fontSize: '0.8rem', textAlign: 'center', padding: '12px', color: 'var(--text-muted)' }}>
                      No available users found.
                    </div>
                  ) : (
                    candidateUsers.map((u) => (
                      <div
                        key={u.id}
                        onClick={() => handleAddMember(u.id)}
                        style={{
                          display: 'flex',
                          alignItems: 'center',
                          justifyContent: 'space-between',
                          padding: '6px 10px',
                          borderRadius: 'var(--radius-sm)',
                          background: 'var(--border-subtle)',
                          cursor: 'pointer',
                        }}
                      >
                        <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                          <Avatar name={u.display_name} src={u.avatar_key} size="xs" />
                          <span style={{ fontSize: '0.833rem' }}>{u.display_name} (@{u.username})</span>
                        </div>
                        <UserPlus size={14} color="var(--accent)" />
                      </div>
                    ))
                  )}
                </div>
              </div>
            )}
          </div>
        )}

        {/* Member List */}
        <div style={{ marginBottom: '20px' }}>
          <h4
            style={{
              fontSize: '0.8rem',
              fontWeight: 600,
              color: 'var(--text-secondary)',
              textTransform: 'uppercase',
              letterSpacing: '0.05em',
              marginBottom: '10px',
            }}
          >
            Members ({activeMembers.length})
          </h4>

          <div style={{ display: 'flex', flexDirection: 'column', gap: '6px', maxHeight: '240px', overflowY: 'auto' }}>
            {activeMembers.map((m) => {
              const isMemberOwner = m.role === 'owner';
              const isCurrentUser = m.user_id === user?.id;
              const name = m.profiles?.display_name || m.profiles?.username || 'User';

              return (
                <div
                  key={m.user_id}
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'space-between',
                    padding: '8px 12px',
                    borderRadius: 'var(--radius-md)',
                    background: 'var(--border-subtle)',
                    border: '1px solid var(--border-subtle)',
                  }}
                >
                  <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
                    <Avatar name={name} src={m.profiles?.avatar_key} size="sm" />
                    <div>
                      <div style={{ fontSize: '0.867rem', fontWeight: 600, display: 'flex', alignItems: 'center', gap: '6px' }}>
                        <span>{name}</span>
                        {isCurrentUser && (
                          <span style={{ fontSize: '0.8rem', color: 'var(--text-muted)' }}>(You)</span>
                        )}
                      </div>
                      <div style={{ fontSize: '0.8rem', color: 'var(--text-muted)' }}>
                        @{m.profiles?.username}
                      </div>
                    </div>
                  </div>

                  <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                    {isMemberOwner ? (
                      <Badge variant="warning" size="sm">
                        <Crown size={11} style={{ marginRight: '3px' }} />
                        Owner
                      </Badge>
                    ) : campusRoom && isCampusRoomAdmin(campusRoom.slug, m.profiles?.username) ? (
                      <Badge variant="primary" size="sm">
                        <ShieldCheck size={11} style={{ marginRight: '3px' }} />
                        Admin
                      </Badge>
                    ) : (
                      <Badge variant="neutral" size="sm">Member</Badge>
                    )}

                    {/* Owner/Admin can remove non-owners */}
                    {isPrivileged && !isMemberOwner && !isCurrentUser && (
                      <button
                        onClick={() => handleRemoveMember(m.user_id, name)}
                        className="action-btn-mini"
                        style={{ color: 'var(--danger)' }}
                        title="Remove member"
                      >
                        <UserMinus size={15} />
                      </button>
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        </div>

        {/* Leave Group Button */}
        <div style={{ paddingTop: '16px', borderTop: '1px solid var(--border-subtle)' }}>
          <button
            type="button"
            onClick={() => handleRemoveMember(user?.id || '', 'You')}
            className="btn btn-danger"
            style={{ width: '100%', padding: '10px' }}
          >
            <LogOut size={16} />
            Leave Group
          </button>
        </div>
      </div>
    </Modal>
  );
};

'use client';

import React, { useState, useEffect } from 'react';
import { Modal } from '@/components/ui/Modal';
import { Avatar } from '@/components/ui/Avatar';
import { useAuth } from '@/context/AuthContext';
import { useToast } from '@/components/ui/Toast';
import { parseRollNumber } from '@/lib/campus';
import { User, LogOut, Save, GraduationCap, Building2 } from 'lucide-react';

interface ProfileModalProps {
  isOpen: boolean;
  onClose: () => void;
}

export const ProfileModal: React.FC<ProfileModalProps> = ({ isOpen, onClose }) => {
  const { user, profile, updateProfile, logout } = useAuth();
  const { success, error } = useToast();

  const [displayName, setDisplayName] = useState(profile?.display_name || '');
  const [avatarKey, setAvatarKey] = useState<string | null>(profile?.avatar_key || null);
  const [isSaving, setIsSaving] = useState(false);



  const parsed = parseRollNumber(profile?.username || '');

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!displayName.trim()) {
      error('Display name cannot be blank');
      return;
    }

    setIsSaving(true);
    try {
      await updateProfile({
        display_name: displayName.trim(),
        avatar_key: avatarKey,
      });
      success('Campus profile updated!');
      onClose();
    } catch (err: unknown) {
      error((err instanceof Error ? err.message : '') || 'Failed to update profile');
    } finally {
      setIsSaving(false);
    }
  };

  const handleLogout = async () => {
    try {
      await logout();
      onClose();
    } catch (err: unknown) {
      error('Logout failed');
    }
  };

  return (
    <Modal
      isOpen={isOpen}
      onClose={onClose}
      title="Campus Profile"
      description="IIT Mandi Intranet Account"
      maxWidth={460}
    >
      <form onSubmit={handleSave}>
        {/* Profile Header Card */}
        <div
          style={{
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            padding: '20px',
            background: 'rgba(0, 0, 0, 0.25)',
            borderRadius: 'var(--radius-lg)',
            border: '1px solid var(--border-subtle)',
            marginBottom: '20px',
            gap: '10px',
          }}
        >
          <Avatar name={displayName || profile?.username} src={avatarKey} size="xl" />
          <div style={{ textAlign: 'center' }}>
            <h4 style={{ fontSize: '1.133rem', fontWeight: 700 }}>
              {displayName || 'Student'}
            </h4>
            <div
              style={{
                display: 'inline-flex',
                alignItems: 'center',
                gap: '6px',
                fontSize: '0.8rem',
                color: 'var(--accent)',
                fontFamily: 'monospace',
                fontWeight: 600,
                marginTop: '3px',
              }}
            >
              <GraduationCap size={14} />
              <span>{profile?.username ? profile.username.toUpperCase() : 'STUDENT'}</span>
              <span>•</span>
              <span>{parsed.hierarchyName || 'IIT Mandi'}</span>
            </div>
            <div style={{ fontSize: '0.8rem', color: 'var(--text-muted)', marginTop: '2px' }}>
              {user?.email || `${profile?.username}@students.iitmandi.ac.in`}
            </div>
          </div>
        </div>

        {/* Display Name Input */}
        <div className="input-group">
          <label className="input-label">Display Name</label>
          <div style={{ position: 'relative' }}>
            <input
              type="text"
              required
              maxLength={80}
              placeholder="Your name"
              className="input-control"
              style={{ paddingLeft: '38px' }}
              value={displayName}
              onChange={(e) => setDisplayName(e.target.value)}
            />
            <User
              size={16}
              style={{
                position: 'absolute',
                left: '12px',
                top: '50%',
                transform: 'translateY(-50%)',
                color: 'var(--text-muted)',
              }}
            />
          </div>
        </div>

        {/* Permanent Enrollment Number Card */}
        <div
          style={{
            padding: '10px 14px',
            borderRadius: 'var(--radius-md)',
            background: 'var(--border-subtle)',
            border: '1px solid var(--border-subtle)',
            fontSize: '0.8rem',
            color: 'var(--text-muted)',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'space-between',
            marginBottom: '20px',
          }}
        >
          <span>Enrollment Number</span>
          <span style={{ color: 'var(--text-primary)', fontWeight: 600, fontFamily: 'monospace' }}>
            {profile?.username?.toUpperCase()}
          </span>
        </div>

        {/* Action buttons */}
        <div
          style={{
            display: 'flex',
            gap: '10px',
            paddingTop: '16px',
            borderTop: '1px solid var(--border-subtle)',
          }}
        >
          <button
            type="button"
            onClick={handleLogout}
            className="btn btn-danger"
            style={{ flex: 1 }}
          >
            <LogOut size={16} />
            Sign Out
          </button>
          <button
            type="submit"
            disabled={isSaving}
            className="btn btn-primary"
            style={{ flex: 1 }}
          >
            <Save size={16} />
            {isSaving ? 'Saving...' : 'Save Changes'}
          </button>
        </div>
      </form>
    </Modal>
  );
};

'use client';

import React, { useState, useEffect } from 'react';
import { Modal } from '@/components/ui/Modal';
import { Avatar } from '@/components/ui/Avatar';
import { api } from '@/lib/api';
import { useChat } from '@/context/ChatContext';
import { useToast } from '@/components/ui/Toast';
import { Profile } from '@/types/chat';
import { searchCampusDirectory } from '@/lib/campus';
import {
  Search,
  Check,
  Users,
  MessageSquarePlus,
  GraduationCap,
  Building2,
} from 'lucide-react';

interface NewConversationModalProps {
  isOpen: boolean;
  onClose: () => void;
}

export const NewConversationModal: React.FC<NewConversationModalProps> = ({
  isOpen,
  onClose,
}) => {
  const { createDirectChat, createGroupChat } = useChat();
  const { error, success } = useToast();

  const [activeTab, setActiveTab] = useState<'direct' | 'group'>('direct');
  const [searchQuery, setSearchQuery] = useState('');
  const [searchResults, setSearchResults] = useState<Profile[]>([]);
  const [isSearching, setIsSearching] = useState(false);

  // Group creation state
  const [groupTitle, setGroupTitle] = useState('');
  const [selectedMemberIds, setSelectedMemberIds] = useState<string[]>([]);
  const [isCreating, setIsCreating] = useState(false);

  // Search registered users by Name or Enrollment Number
  useEffect(() => {
    if (!isOpen) return;

    let active = true;
    const timer = setTimeout(async () => {
      setIsSearching(true);
      try {
        const res = await api.searchUsers(searchQuery.trim());
        if (active && res.data) {
          setSearchResults(res.data);
        }
      } catch (err: unknown) {
        console.error('Failed to search users:', err);
      } finally {
        if (active) setIsSearching(false);
      }
    }, 200);

    return () => { active = false; clearTimeout(timer); };
  }, [searchQuery, isOpen]);

  // Also query campus directory to give hints
  const directoryMatches = searchQuery.trim().length >= 2
    ? searchCampusDirectory(searchQuery.trim(), 8)
    : [];

  const handleStartDirect = async (user: Profile) => {
    setIsCreating(true);
    try {
      await createDirectChat(user.id);
      success(`Chat started with ${user.display_name || user.username}`);
      onClose();
    } catch (err: unknown) {
      error((err instanceof Error ? err.message : '') || 'Failed to start direct chat');
    } finally {
      setIsCreating(false);
    }
  };

  const handleToggleMember = (userId: string) => {
    setSelectedMemberIds((prev) =>
      prev.includes(userId) ? prev.filter((id) => id !== userId) : [...prev, userId]
    );
  };

  const handleCreateGroup = async () => {
    if (!groupTitle.trim()) {
      error('Please enter a group title');
      return;
    }
    if (selectedMemberIds.length === 0) {
      error('Please select at least one registered student');
      return;
    }

    setIsCreating(true);
    try {
      await createGroupChat(groupTitle.trim(), selectedMemberIds);
      success(`Group "${groupTitle}" created!`);
      setGroupTitle('');
      setSelectedMemberIds([]);
      onClose();
    } catch (err: unknown) {
      error((err instanceof Error ? err.message : '') || 'Failed to create group');
    } finally {
      setIsCreating(false);
    }
  };

  return (
    <Modal
      isOpen={isOpen}
      onClose={onClose}
      title="Start Campus Conversation"
      description="Connect across North & South Campuses by name or enrollment number"
      maxWidth={520}
    >
      <div>
        {/* Tabs */}
        <div
          style={{
            display: 'flex',
            background: 'rgba(0, 0, 0, 0.3)',
            borderRadius: 'var(--radius-md)',
            padding: '3px',
            marginBottom: '18px',
            border: '1px solid var(--border-subtle)',
          }}
        >
          <button
            type="button"
            onClick={() => setActiveTab('direct')}
            style={{
              flex: 1,
              padding: '8px',
              border: 'none',
              borderRadius: 'var(--radius-sm)',
              fontSize: '0.867rem',
              fontWeight: 600,
              cursor: 'pointer',
              background: activeTab === 'direct' ? 'var(--accent)' : 'transparent',
              color: activeTab === 'direct' ? '#ffffff' : 'var(--text-secondary)',
              transition: 'all var(--transition-fast)',
            }}
          >
            Direct Chat
          </button>
          <button
            type="button"
            onClick={() => setActiveTab('group')}
            style={{
              flex: 1,
              padding: '8px',
              border: 'none',
              borderRadius: 'var(--radius-sm)',
              fontSize: '0.867rem',
              fontWeight: 600,
              cursor: 'pointer',
              background: activeTab === 'group' ? 'var(--accent)' : 'transparent',
              color: activeTab === 'group' ? '#ffffff' : 'var(--text-secondary)',
              transition: 'all var(--transition-fast)',
            }}
          >
            Create Campus Group
          </button>
        </div>

        {/* Group Title input if on group tab */}
        {activeTab === 'group' && (
          <div className="input-group" style={{ marginBottom: '16px' }}>
            <label className="input-label">Group Title</label>
            <input
              type="text"
              placeholder="e.g. North Campus Hostel 7, CS202 Study Group"
              className="input-control"
              value={groupTitle}
              onChange={(e) => setGroupTitle(e.target.value)}
              maxLength={120}
            />
          </div>
        )}

        {/* Search Users Input */}
        <div className="search-box" style={{ marginBottom: '14px' }}>
          <Search size={16} className="search-icon" />
          <input
            type="text"
            placeholder="Search by student name or roll number (e.g. B26001, Aarti)..."
            className="search-input"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            autoFocus
          />
        </div>

        {/* Results Container */}
        <div
          style={{
            maxHeight: '290px',
            overflowY: 'auto',
            display: 'flex',
            flexDirection: 'column',
            gap: '6px',
          }}
        >
          {isSearching ? (
            <div style={{ padding: '24px', textAlign: 'center', color: 'var(--text-muted)' }}>
              Searching campus records...
            </div>
          ) : searchResults.length === 0 ? (
            <div
              style={{
                padding: '24px 16px',
                textAlign: 'center',
                color: 'var(--text-muted)',
                display: 'flex',
                flexDirection: 'column',
                gap: '8px',
                alignItems: 'center',
              }}
            >
              <div>
                {searchQuery
                  ? `No registered students matching "${searchQuery}".`
                  : 'Type a student name or enrollment number to search.'}
              </div>

              {/* Show directory hints if matching directory but not yet signed in */}
              {directoryMatches.length > 0 && (
                <div style={{ marginTop: '10px', width: '100%', textAlign: 'left' }}>
                  <div style={{ fontSize: '0.8rem', color: 'var(--accent)', fontWeight: 700, marginBottom: '6px' }}>
                    Matching Campus Directory Records:
                  </div>
                  <div style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
                    {directoryMatches.map((d) => (
                      <div
                        key={d.id}
                        style={{
                          padding: '6px 10px',
                          borderRadius: 'var(--radius-sm)',
                          background: 'var(--accent-light)',
                          fontSize: '0.8rem',
                          display: 'flex',
                          justifyContent: 'space-between',
                        }}
                      >
                        <span style={{ fontWeight: 600, color: '#f8fafc' }}>{d.name}</span>
                        <span style={{ color: 'var(--accent)', fontFamily: 'monospace' }}>{d.id}</span>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
          ) : (
            searchResults.map((user) => {
              const isSelected = selectedMemberIds.includes(user.id);
              const rollTag = user.username ? `@${user.username.toUpperCase()}` : '';

              return (
                <div
                  key={user.id}
                  onClick={() => {
                    if (activeTab === 'direct') {
                      handleStartDirect(user);
                    } else {
                      handleToggleMember(user.id);
                    }
                  }}
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'space-between',
                    padding: '8px 12px',
                    borderRadius: 'var(--radius-md)',
                    background: isSelected ? 'var(--accent-light)' : 'var(--border-subtle)',
                    border: `1px solid ${isSelected ? 'var(--accent-light)' : 'var(--border-subtle)'}`,
                    cursor: 'pointer',
                    transition: 'all var(--transition-fast)',
                  }}
                >
                  <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
                    <Avatar name={user.display_name || user.username} src={user.avatar_key} size="sm" />
                    <div>
                      <div style={{ fontSize: '0.9rem', fontWeight: 600, color: 'var(--text-primary)' }}>
                        {user.display_name}
                      </div>
                      <div style={{ fontSize: '0.8rem', color: 'var(--accent)', fontFamily: 'monospace' }}>
                        {rollTag}
                      </div>
                    </div>
                  </div>

                  {activeTab === 'direct' ? (
                    <button
                      type="button"
                      className="btn-icon btn-ghost"
                      style={{ color: 'var(--accent)' }}
                      title="Chat"
                    >
                      <MessageSquarePlus size={18} />
                    </button>
                  ) : (
                    <div
                      style={{
                        width: 20,
                        height: 20,
                        borderRadius: '6px',
                        border: `1.5px solid ${isSelected ? 'var(--accent)' : 'var(--border-medium)'}`,
                        background: isSelected ? 'var(--accent)' : 'transparent',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        color: 'white',
                      }}
                    >
                      {isSelected && <Check size={14} />}
                    </div>
                  )}
                </div>
              );
            })
          )}
        </div>

        {/* Group creation submit button */}
        {activeTab === 'group' && (
          <div style={{ marginTop: '18px' }}>
            <button
              type="button"
              onClick={handleCreateGroup}
              disabled={isCreating || selectedMemberIds.length === 0 || !groupTitle.trim()}
              className="btn btn-primary"
              style={{ width: '100%', padding: '12px' }}
            >
              {isCreating
                ? 'Creating Group...'
                : `Create Campus Group (${selectedMemberIds.length} members)`}
            </button>
          </div>
        )}
      </div>
    </Modal>
  );
};

'use client';

import React, { useState, useMemo } from 'react';
import { useChat } from '@/context/ChatContext';
import { useAuth } from '@/context/AuthContext';
import { useToast } from '@/components/ui/Toast';
import { api } from '@/lib/api';
import { ALL_CAMPUS_ROOMS } from '@/lib/campus-rooms';
import { CampusRoom } from '@/types/chat';
import { ConversationItem } from './ConversationItem';
import { NewConversationModal } from './NewConversationModal';
import { ProfileModal } from '@/components/profile/ProfileModal';
import { useVisualSettings } from '@/components/settings/VisualSettings';
import { Avatar } from '@/components/ui/Avatar';
import {
  getOtherMember,
  getMemberProfile,
} from '@/lib/utils';
import {
  Plus,
  Search,
  Settings,
  WifiOff,
  GraduationCap,
  MessageSquare,
  Calendar,
  Wrench,
  UtensilsCrossed,
  Sparkles,
  Building,
  Users,
  Layers,
  Check,
  ChevronRight,
  Flame,
  BookOpen,
  Trophy,
} from 'lucide-react';

interface SidebarProps {
  isMobileOpen?: boolean;
  onCloseMobile?: () => void;
  onOpenCalendar?: (organizer?: string) => void;
  onOpenTickets?: (scope?: 'hostel' | 'mess', clusterOrMess?: string) => void;
  onOpenMoodle?: (courseCode?: string) => void;
  onOpenMessMenu?: (messSlug?: string) => void;
}

type MainTab = 'dms' | 'clubs' | 'courses' | 'hostels' | 'branches' | 'messes';

export const Sidebar: React.FC<SidebarProps> = ({
  isMobileOpen = true,
  onCloseMobile,
  onOpenCalendar,
  onOpenTickets,
  onOpenMoodle,
  onOpenMessMenu,
}) => {
  const {
    conversations,
    activeConversationId,
    selectConversation,
    refreshConversations,
    isLoadingConversations,
    connectionStatus,
    typingUserIds,
  } = useChat();
  const { user, profile } = useAuth();
  const { openSettings } = useVisualSettings();
  const { error: toastError, success: toastSuccess } = useToast();

  const [mainTab, setMainTab] = useState<MainTab>('dms');
  const [filterType, setFilterType] = useState<'all' | 'direct' | 'group'>('all');
  const [subFilter, setSubFilter] = useState<string>('all');
  const [searchQuery, setSearchQuery] = useState('');
  const [isNewModalOpen, setIsNewModalOpen] = useState(false);
  const [isProfileModalOpen, setIsProfileModalOpen] = useState(false);
  const [joiningSlug, setJoiningSlug] = useState<string | null>(null);

  // Filtered DMs & Custom Groups
  const filteredConversations = useMemo(() => {
    return conversations.filter((c) => {
      if (filterType !== 'all' && c.type !== filterType) return false;

      if (searchQuery.trim()) {
        const query = searchQuery.toLowerCase();
        if (c.title?.toLowerCase().includes(query)) return true;
        const otherMember = getOtherMember(c, user?.id);
        const otherProfile = getMemberProfile(otherMember);
        const name = otherProfile?.display_name?.toLowerCase();
        const username = otherProfile?.username?.toLowerCase();
        if (name?.includes(query) || username?.includes(query)) return true;
        return false;
      }
      return true;
    });
  }, [conversations, filterType, searchQuery, user?.id]);

  // Filtered Campus Scoped Rooms
  const filteredCampusRooms = useMemo(() => {
    if (mainTab === 'dms') return [];

    let rooms = ALL_CAMPUS_ROOMS.filter((r) => r.category === mainTab);

    // Apply subfilters
    if (subFilter !== 'all') {
      if (mainTab === 'clubs') {
        rooms = rooms.filter((r) =>
          r.subcategory.toLowerCase().includes(subFilter.toLowerCase())
        );
      } else if (mainTab === 'hostels') {
        if (subFilter === 'North' || subFilter === 'South') {
          rooms = rooms.filter((r) => r.campus === subFilter);
        } else if (subFilter === 'clusters') {
          rooms = rooms.filter((r) => r.slug.includes('general') || r.subcategory.includes('Cluster'));
        }
      } else if (mainTab === 'courses') {
        if (subFilter === 'core') {
          rooms = rooms.filter((r) => r.subcategory.includes('Institute Core'));
        } else if (subFilter === 'dept') {
          rooms = rooms.filter((r) => r.subcategory.includes('Department Core'));
        } else if (subFilter === 'practicum') {
          rooms = rooms.filter((r) => r.subcategory.includes('Practicum'));
        }
      } else if (mainTab === 'branches') {
        if (subFilter === 'btech') {
          rooms = rooms.filter((r) => r.subcategory.includes('B.Tech'));
        } else if (subFilter === 'dual') {
          rooms = rooms.filter((r) => r.subcategory.includes('Dual') || r.subcategory.includes('BS'));
        } else if (subFilter === 'pg') {
          rooms = rooms.filter((r) => r.subcategory.includes('M.Tech') || r.subcategory.includes('M.Sc') || r.subcategory.includes('MBA'));
        } else if (subFilter === 'research') {
          rooms = rooms.filter((r) => r.subcategory.includes('Research'));
        }
      } else if (mainTab === 'messes') {
        if (subFilter === 'North' || subFilter === 'South') {
          rooms = rooms.filter((r) => r.campus === subFilter);
        }
      }
    }

    // Apply search query
    if (searchQuery.trim()) {
      const q = searchQuery.toLowerCase();
      rooms = rooms.filter(
        (r) =>
          r.name.toLowerCase().includes(q) ||
          r.slug.toLowerCase().includes(q) ||
          r.subcategory.toLowerCase().includes(q) ||
          (r.courseCode && r.courseCode.toLowerCase().includes(q)) ||
          r.tags.some((t) => t.toLowerCase().includes(q))
      );
    }

    return rooms;
  }, [mainTab, subFilter, searchQuery]);

  const handleJoinCampusRoom = async (room: CampusRoom) => {
    if (joiningSlug) return;
    setJoiningSlug(room.slug);
    try {
      const res = await api.joinCampusRoomConversation(room.slug);
      if (res.data?.conversation) {
        await refreshConversations();
        await selectConversation(res.data.conversation.id);
        onCloseMobile?.();
        toastSuccess(`Joined #${room.name}`);
      }
    } catch (err: unknown) {
      console.error('Failed to join room:', err);
      toastError((err instanceof Error ? err.message : '') || `Could not join #${room.name}`);
    } finally {
      setJoiningSlug(null);
    }
  };

  const rollNumberDisplay = profile?.username
    ? `@${profile.username.toUpperCase()}`
    : '';

  const getRoomIcon = (cat: CampusRoom['category']) => {
    switch (cat) {
      case 'clubs':
        return <Trophy size={16} className="text-[var(--accent)]" />;
      case 'courses':
        return <BookOpen size={16} className="text-[var(--accent)]" />;
      case 'hostels':
        return <Building size={16} className="text-[var(--accent)]" />;
      case 'branches':
        return <GraduationCap size={16} className="text-[var(--accent)]" />;
      case 'messes':
        return <UtensilsCrossed size={16} className="text-[var(--accent)]" />;
    }
  };

  return (
    <>
      <aside className={`sidebar ${!isMobileOpen ? 'hidden-mobile' : ''}`}>
        {/* Brand & Action Header */}
        <div className="sidebar-header">
          <div className="sidebar-brand">
            <div
              className="brand-icon"
              style={{
                background: 'var(--accent)',
                boxShadow: '0 4px 12px var(--accent-light)',
              }}
            >
              <GraduationCap size={19} />
            </div>
            <div style={{ display: 'flex', flexDirection: 'column' }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
                <span className="brand-title">KamandChat</span>
                {connectionStatus === 'connected' ? (
                  <span title="Intranet Connected" style={{ display: 'flex' }}>
                    <span className="status-dot online pulsing" />
                  </span>
                ) : connectionStatus === 'connecting' ? (
                  <span title="Connecting to Kamand gateway..." style={{ display: 'flex' }}>
                    <span className="status-dot pulsing" style={{ backgroundColor: '#f59e0b' }} />
                  </span>
                ) : (
                  <span title="Gateway Offline" style={{ display: 'flex', color: 'var(--danger)' }}>
                    <WifiOff size={13} />
                  </span>
                )}
              </div>
              <span style={{ fontSize: '0.8rem', color: 'var(--text-muted)', letterSpacing: '0.02em' }}>
                IIT Mandi &bull; North &amp; South
              </span>
            </div>
          </div>

          <button
            onClick={() => setIsNewModalOpen(true)}
            className="btn btn-primary"
            style={{
              padding: '7px 12px',
              fontSize: '0.833rem',
              borderRadius: 'var(--radius-full)',
              background: 'var(--accent)',
            }}
          >
            <Plus size={15} />
            <span>New Chat</span>
          </button>
        </div>

        {/* Quick Utility Launchers Bar */}
        <div
          style={{
            display: 'grid',
            gridTemplateColumns: 'repeat(4, 1fr)',
            gap: '6px',
            padding: '4px 16px 10px',
            borderBottom: '1px solid var(--border-subtle)',
          }}
        >
          <button
            onClick={() => onOpenCalendar?.()}
            className="btn btn-ghost"
            style={{
              display: 'flex',
              flexDirection: 'column',
              alignItems: 'center',
              padding: '6px 4px',
              borderRadius: '8px',
              fontSize: '0.8rem',
              gap: '4px',
              background: 'var(--accent-light)',
              color: 'var(--accent)',
              border: '1px solid var(--accent-light)',
            }}
            title="Unified Gymkhana Calendar & Venue Bookings"
          >
            <Calendar size={14} className="text-[var(--accent)]" />
            <span>Calendar</span>
          </button>

          <button
            onClick={() => onOpenTickets?.('hostel')}
            className="btn btn-ghost"
            style={{
              display: 'flex',
              flexDirection: 'column',
              alignItems: 'center',
              padding: '6px 4px',
              borderRadius: '8px',
              fontSize: '0.8rem',
              gap: '4px',
              background: 'var(--accent-light)',
              color: '#bae6fd',
              border: '1px solid var(--accent-light)',
            }}
            title="Hostel & Mess Maintenance Tickets"
          >
            <Wrench size={14} className="text-[var(--accent)]" />
            <span>Tickets</span>
          </button>

          <button
            onClick={() => onOpenMoodle?.()}
            className="btn btn-ghost"
            style={{
              display: 'flex',
              flexDirection: 'column',
              alignItems: 'center',
              padding: '6px 4px',
              borderRadius: '8px',
              fontSize: '0.8rem',
              gap: '4px',
              background: 'var(--accent-light)',
              color: 'var(--accent)',
              border: '1px solid var(--accent-light)',
            }}
            title="IIT Mandi Moodle LMS Sync"
          >
            <GraduationCap size={14} className="text-[var(--accent)]" />
            <span>Moodle</span>
          </button>

          <button
            onClick={() => onOpenMessMenu?.()}
            className="btn btn-ghost"
            style={{
              display: 'flex',
              flexDirection: 'column',
              alignItems: 'center',
              padding: '6px 4px',
              borderRadius: '8px',
              fontSize: '0.8rem',
              gap: '4px',
              background: 'rgba(245, 158, 11, 0.08)',
              color: '#fde68a',
              border: '1px solid rgba(245, 158, 11, 0.15)',
            }}
            title="Mess Menus & Rebate Portal"
          >
            <UtensilsCrossed size={14} className="text-[var(--accent)]" />
            <span>Messes</span>
          </button>
        </div>

        {/* 6 Category Switcher Navigation Tabs */}
        <div
          style={{
            display: 'flex',
            alignItems: 'center',
            padding: '8px 14px 4px',
            gap: '4px',
            overflowX: 'auto',
          }}
        >
          <button
            onClick={() => {
              setMainTab('dms');
              setSubFilter('all');
            }}
            className={`nav-pill ${mainTab === 'dms' ? 'active' : ''}`}
            style={{ whiteSpace: 'nowrap', padding: '5px 10px', fontSize: '0.8rem' }}
          >
            DMs ({conversations.length})
          </button>
          <button
            onClick={() => {
              setMainTab('clubs');
              setSubFilter('all');
            }}
            className={`nav-pill ${mainTab === 'clubs' ? 'active' : ''}`}
            style={{ whiteSpace: 'nowrap', padding: '5px 10px', fontSize: '0.8rem' }}
          >
            Clubs
          </button>
          <button
            onClick={() => {
              setMainTab('courses');
              setSubFilter('all');
            }}
            className={`nav-pill ${mainTab === 'courses' ? 'active' : ''}`}
            style={{ whiteSpace: 'nowrap', padding: '5px 10px', fontSize: '0.8rem' }}
          >
            Courses
          </button>
          <button
            onClick={() => {
              setMainTab('hostels');
              setSubFilter('all');
            }}
            className={`nav-pill ${mainTab === 'hostels' ? 'active' : ''}`}
            style={{ whiteSpace: 'nowrap', padding: '5px 10px', fontSize: '0.8rem' }}
          >
            Hostels
          </button>
          <button
            onClick={() => {
              setMainTab('branches');
              setSubFilter('all');
            }}
            className={`nav-pill ${mainTab === 'branches' ? 'active' : ''}`}
            style={{ whiteSpace: 'nowrap', padding: '5px 10px', fontSize: '0.8rem' }}
          >
            Branches
          </button>
          <button
            onClick={() => {
              setMainTab('messes');
              setSubFilter('all');
            }}
            className={`nav-pill ${mainTab === 'messes' ? 'active' : ''}`}
            style={{ whiteSpace: 'nowrap', padding: '5px 10px', fontSize: '0.8rem' }}
          >
            Messes
          </button>
        </div>

        {/* Sub-Filters / Pills for Selected Category */}
        <div style={{ display: 'flex', padding: '2px 16px 8px', gap: '6px', overflowX: 'auto' }}>
          {mainTab === 'dms' && (
            <>
              <button
                className={`nav-pill ${filterType === 'all' ? 'active' : ''}`}
                onClick={() => setFilterType('all')}
                style={{ fontSize: '0.8rem', padding: '3px 8px' }}
              >
                All
              </button>
              <button
                className={`nav-pill ${filterType === 'direct' ? 'active' : ''}`}
                onClick={() => setFilterType('direct')}
                style={{ fontSize: '0.8rem', padding: '3px 8px' }}
              >
                Direct
              </button>
              <button
                className={`nav-pill ${filterType === 'group' ? 'active' : ''}`}
                onClick={() => setFilterType('group')}
                style={{ fontSize: '0.8rem', padding: '3px 8px' }}
              >
                Groups
              </button>
            </>
          )}

          {mainTab === 'clubs' && (
            <>
              {['all', 'SnTC', 'SAC', 'Sports', 'Fest'].map((f) => (
                <button
                  key={f}
                  className={`nav-pill ${subFilter === f ? 'active' : ''}`}
                  onClick={() => setSubFilter(f)}
                  style={{ fontSize: '0.8rem', padding: '3px 8px' }}
                >
                  {f === 'all' ? 'All Clubs' : f}
                </button>
              ))}
            </>
          )}

          {mainTab === 'courses' && (
            <>
              {[
                { id: 'all', label: 'All Courses' },
                { id: 'core', label: 'Institute Core' },
                { id: 'dept', label: 'Dept Core' },
                { id: 'practicum', label: 'Practicum' },
              ].map((f) => (
                <button
                  key={f.id}
                  className={`nav-pill ${subFilter === f.id ? 'active' : ''}`}
                  onClick={() => setSubFilter(f.id)}
                  style={{ fontSize: '0.8rem', padding: '3px 8px' }}
                >
                  {f.label}
                </button>
              ))}
            </>
          )}

          {mainTab === 'hostels' && (
            <>
              {[
                { id: 'all', label: 'All Hostels' },
                { id: 'North', label: 'North Campus' },
                { id: 'South', label: 'South Campus' },
                { id: 'clusters', label: 'General / Clusters' },
              ].map((f) => (
                <button
                  key={f.id}
                  className={`nav-pill ${subFilter === f.id ? 'active' : ''}`}
                  onClick={() => setSubFilter(f.id)}
                  style={{ fontSize: '0.8rem', padding: '3px 8px' }}
                >
                  {f.label}
                </button>
              ))}
            </>
          )}

          {mainTab === 'branches' && (
            <>
              {[
                { id: 'all', label: 'All Programs' },
                { id: 'btech', label: 'B.Tech' },
                { id: 'dual', label: 'Dual / BS' },
                { id: 'pg', label: 'PG / Masters' },
                { id: 'research', label: 'Research' },
              ].map((f) => (
                <button
                  key={f.id}
                  className={`nav-pill ${subFilter === f.id ? 'active' : ''}`}
                  onClick={() => setSubFilter(f.id)}
                  style={{ fontSize: '0.8rem', padding: '3px 8px' }}
                >
                  {f.label}
                </button>
              ))}
            </>
          )}

          {mainTab === 'messes' && (
            <>
              {[
                { id: 'all', label: 'All Dining Halls' },
                { id: 'North', label: 'North Messes' },
                { id: 'South', label: 'South Mess' },
              ].map((f) => (
                <button
                  key={f.id}
                  className={`nav-pill ${subFilter === f.id ? 'active' : ''}`}
                  onClick={() => setSubFilter(f.id)}
                  style={{ fontSize: '0.8rem', padding: '3px 8px' }}
                >
                  {f.label}
                </button>
              ))}
            </>
          )}
        </div>

        {/* Search */}
        <div className="sidebar-search">
          <div className="search-box">
            <Search size={15} className="search-icon" />
            <input
              type="text"
              placeholder={
                mainTab === 'dms'
                  ? 'Search students, groups, roll #...'
                  : `Search ${mainTab} (e.g. B18, IC152, SnTC)...`
              }
              className="search-input"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
            />
          </div>
        </div>

        {/* Content List: Either DMs or Scoped Campus Rooms */}
        <div className="conversation-list">
          {mainTab === 'dms' ? (
            /* DMs List */
            isLoadingConversations && conversations.length === 0 ? (
              <div style={{ padding: '30px', textAlign: 'center', color: 'var(--text-muted)' }}>
                Loading campus chats...
              </div>
            ) : filteredConversations.length === 0 ? (
              <div
                style={{
                  padding: '36px 20px',
                  textAlign: 'center',
                  color: 'var(--text-secondary)',
                  display: 'flex',
                  flexDirection: 'column',
                  alignItems: 'center',
                  gap: '10px',
                }}
              >
                <div
                  style={{
                    width: '44px',
                    height: '44px',
                    borderRadius: '50%',
                    background: 'var(--border-subtle)',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    color: 'var(--text-muted)',
                  }}
                >
                  <MessageSquare size={20} />
                </div>
                <p style={{ fontSize: '0.867rem' }}>
                  {searchQuery ? 'No conversations matching search' : 'No direct conversations yet'}
                </p>
                <button
                  onClick={() => setIsNewModalOpen(true)}
                  className="btn btn-secondary"
                  style={{ fontSize: '0.8rem', padding: '6px 12px' }}
                >
                  Message a student
                </button>
              </div>
            ) : (
              filteredConversations.map((c) => (
                <ConversationItem
                  key={c.id}
                  conversation={c}
                  isActive={c.id === activeConversationId}
                  currentUserId={user?.id || ''}
                  isTyping={c.id === activeConversationId && typingUserIds.length > 0}
                  onClick={() => {
                    selectConversation(c.id);
                    onCloseMobile?.();
                  }}
                />
              ))
            )
          ) : (
            /* Scoped Campus Rooms List */
            filteredCampusRooms.length === 0 ? (
              <div
                style={{
                  padding: '36px 20px',
                  textAlign: 'center',
                  color: 'var(--text-secondary)',
                  display: 'flex',
                  flexDirection: 'column',
                  alignItems: 'center',
                  gap: '10px',
                }}
              >
                <Building size={32} style={{ color: 'var(--text-muted)' }} />
                <p style={{ fontSize: '0.867rem' }}>No {mainTab} found matching filter</p>
              </div>
            ) : (
              filteredCampusRooms.map((room) => {
                const isJoining = joiningSlug === room.slug;
                // Check if user already has this room active
                const existingConv = conversations.find(
                  (c) => c.title === `#${room.name}` || c.title === room.name
                );
                const isActive = existingConv && existingConv.id === activeConversationId;

                return (
                  <div
                    key={room.id}
                    onClick={() => handleJoinCampusRoom(room)}
                    role="button" tabIndex={0} aria-disabled={!!joiningSlug} onKeyDown={e => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); handleJoinCampusRoom(room); } }}
                    className={`conversation-item ${isActive ? 'active' : ''}`}
                    style={{
                      cursor: 'pointer',
                      borderRadius: '12px',
                      padding: '10px 12px',
                      marginBottom: '4px',
                      border: isActive
                        ? '1px solid var(--accent-light)'
                        : '1px solid var(--border-subtle)',
                      background: isActive
                        ? 'var(--accent-light)'
                        : 'var(--border-subtle)',
                      transition: 'all 0.15s ease',
                    }}
                  >
                    <div
                      style={{
                        width: '38px',
                        height: '38px',
                        borderRadius: '10px',
                        background: 'var(--border-subtle)',
                        border: '1px solid var(--border-subtle)',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        flexShrink: 0,
                      }}
                    >
                      {getRoomIcon(room.category)}
                    </div>

                    <div style={{ flex: 1, minWidth: 0 }}>
                      <div
                        style={{
                          display: 'flex',
                          alignItems: 'center',
                          justifyContent: 'space-between',
                          gap: '6px',
                        }}
                      >
                        <span
                          style={{
                            fontSize: '0.867rem',
                            fontWeight: 600,
                            color: 'var(--text-primary)',
                            overflow: 'hidden',
                            textOverflow: 'ellipsis',
                            whiteSpace: 'nowrap',
                          }}
                        >
                          #{room.name}
                        </span>

                        {room.campus && (
                          <span
                            style={{
                              fontSize: '0.8rem',
                              padding: '1px 6px',
                              borderRadius: '4px',
                              background:
                                room.campus === 'North'
                                  ? 'var(--accent-light)'
                                  : room.campus === 'South'
                                  ? 'rgba(245, 158, 11, 0.12)'
                                  : 'var(--accent-light)',
                              color:
                                room.campus === 'North'
                                  ? 'var(--accent)'
                                  : room.campus === 'South'
                                  ? '#fcd34d'
                                  : 'var(--accent)',
                              fontWeight: 600,
                              whiteSpace: 'nowrap',
                            }}
                          >
                            {room.campus}
                          </span>
                        )}
                      </div>

                      <div
                        style={{
                          display: 'flex',
                          alignItems: 'center',
                          justifyContent: 'space-between',
                          marginTop: '2px',
                        }}
                      >
                        <span
                          style={{
                            fontSize: '0.8rem',
                            color: 'var(--text-muted)',
                            overflow: 'hidden',
                            textOverflow: 'ellipsis',
                            whiteSpace: 'nowrap',
                          }}
                        >
                          {room.subcategory}
                        </span>

                        {isJoining ? (
                          <span style={{ fontSize: '0.8rem', color: 'var(--accent)' }}>Joining...</span>
                        ) : existingConv ? (
                          <span
                            style={{
                              fontSize: '0.8rem',
                              color: '#34d399',
                              display: 'flex',
                              alignItems: 'center',
                              gap: '2px',
                            }}
                          >
                            <Check size={11} /> Joined
                          </span>
                        ) : (
                          <span
                            style={{
                              fontSize: '0.8rem',
                              color: 'var(--text-muted)',
                              display: 'flex',
                              alignItems: 'center',
                            }}
                          >
                            Join &rarr;
                          </span>
                        )}
                      </div>
                    </div>
                  </div>
                );
              })
            )
          )}
        </div>

        {/* User Profile & Settings Footer */}
        <div className="sidebar-footer">
          <div
            className="user-profile-preview"
            role="button" tabIndex={0} onKeyDown={e => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); setIsProfileModalOpen(true); } }}
            onClick={() => setIsProfileModalOpen(true)}
            title="Click to view campus profile"
          >
            <Avatar
              name={profile?.display_name || profile?.username}
              src={profile?.avatar_key}
              size="sm"
              online={true}
            />
            <div className="user-profile-info">
              <span className="user-profile-name">
                {profile?.display_name || 'Student'}
              </span>
              <span
                className="user-profile-handle"
                style={{ fontFamily: 'monospace', color: 'var(--accent)' }}
              >
                {rollNumberDisplay || '@student'}
              </span>
            </div>
          </div>

          <button
            onClick={openSettings}
            className="btn-icon btn-ghost"
            aria-label="Visual settings"
            title="Visual settings"
          >
            <Settings size={18} />
          </button>
        </div>
      </aside>

      {/* Modals */}
      <NewConversationModal
        isOpen={isNewModalOpen}
        onClose={() => setIsNewModalOpen(false)}
      />
      {isProfileModalOpen && <ProfileModal
        isOpen={isProfileModalOpen}
        onClose={() => setIsProfileModalOpen(false)}
      />}
    </>
  );
};

'use client';

import React from 'react';
import { getAvatarGradient, getInitials } from '@/lib/utils';

interface AvatarProps {
  name?: string | null;
  src?: string | null;
  size?: 'xs' | 'sm' | 'md' | 'lg' | 'xl';
  online?: boolean;
  className?: string;
  onClick?: () => void;
}

const SIZE_MAP = {
  xs: { size: 24, font: 10, dot: 6 },
  sm: { size: 32, font: 12, dot: 8 },
  md: { size: 40, font: 14, dot: 10 },
  lg: { size: 52, font: 18, dot: 12 },
  xl: { size: 72, font: 24, dot: 14 },
};

export const Avatar: React.FC<AvatarProps> = ({
  name = 'User',
  src,
  size = 'md',
  online,
  className = '',
  onClick,
}) => {
  const { size: pixelSize, font, dot } = SIZE_MAP[size];
  const gradient = getAvatarGradient(name || 'pulse');
  const initials = getInitials(name);

  return (
    <div
      onClick={onClick}
      style={{
        width: pixelSize,
        height: pixelSize,
        minWidth: pixelSize,
        minHeight: pixelSize,
        position: 'relative',
        cursor: onClick ? 'pointer' : 'default',
      }}
      className={className}
    >
      <div
        style={{
          width: '100%',
          height: '100%',
          borderRadius: '50%',
          background: src ? 'transparent' : gradient,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          color: 'var(--text-primary)',
          fontWeight: 700,
          fontSize: font,
          letterSpacing: '-0.02em',
          userSelect: 'none',
          boxShadow: '0 2px 8px rgba(0, 0, 0, 0.25)',
          overflow: 'hidden',
          border: '1.5px solid rgba(255, 255, 255, 0.12)',
        }}
      >
        {src ? (
          <img
            src={src}
            alt={name || 'Avatar'}
            style={{ width: '100%', height: '100%', objectFit: 'cover' }}
          />
        ) : (
          initials
        )}
      </div>

      {online !== undefined && (
        <span
          style={{
            position: 'absolute',
            bottom: 0,
            right: 0,
            width: dot,
            height: dot,
            borderRadius: '50%',
            backgroundColor: online ? '#10b981' : '#64748b',
            border: '2px solid #0e1526',
            boxShadow: online ? '0 0 8px rgba(16, 185, 129, 0.6)' : 'none',
          }}
        />
      )}
    </div>
  );
};

import { io, Socket } from 'socket.io-client';
import { api } from './api';

const SOCKET_URL = process.env.NEXT_PUBLIC_API_URL || 'http://localhost:4000';

type Listener = (payload: unknown) => void;

class SocketManager {
  private socket: Socket | null = null;
  private listeners: Map<string, Set<Listener>> = new Map();
  private lastTypingSent: number = 0;
  private isConnecting: boolean = false;

  connect(token: string) {
    if (this.socket && this.socket.connected) {
      if ((this.socket.auth as { token?: string })?.token === token) {
        return;
      }
      this.disconnect();
    }

    if (this.isConnecting) return;
    this.isConnecting = true;

    this.socket = io(SOCKET_URL, {
      transports: ['websocket'],
      auth: { token },
      reconnection: true,
      reconnectionAttempts: 10,
      reconnectionDelay: 1000,
      reconnectionDelayMax: 5000,
    });

    this.socket.on('connect', () => {
      this.isConnecting = false;
      this.dispatch('connection:status', { connected: true, status: 'connected' });
    });

    this.socket.on('disconnect', (reason) => {
      this.isConnecting = false;
      this.dispatch('connection:status', { connected: false, status: 'disconnected', reason });
    });

    this.socket.on('connect_error', (err) => {
      this.isConnecting = false;
      this.dispatch('connection:status', { connected: false, status: 'error', error: err.message });
    });

    // Real-time server events
    const serverEvents = [
      'message:new',
      'message:updated',
      'message:deleted',
      'message:reaction',
      'conversation:updated',
      'conversation:removed',
      'conversation:read',
      'typing',
      'session:expired',
    ];

    for (const eventName of serverEvents) {
      this.socket.on(eventName, (payload: unknown) => {
        if (eventName === 'session:expired') {
          // Token expired, attempt refresh
          api.refreshTokenIfNeeded().then((newToken) => {
            if (newToken && this.socket) {
              this.socket.auth = { token: newToken };
              this.socket.disconnect().connect();
            }
          });
        }
        this.dispatch(eventName, payload);
      });
    }
  }

  updateToken(token: string) {
    if (this.socket) {
      this.socket.auth = { token };
      this.socket.disconnect().connect();
    }
  }

  disconnect() {
    if (this.socket) {
      this.socket.disconnect();
      this.socket = null;
      this.isConnecting = false;
      this.dispatch('connection:status', { connected: false, status: 'disconnected' });
    }
  }

  on<T>(event: string, listener: (payload: T) => void) {
    const wrapped: Listener = payload => listener(payload as T);
    if (!this.listeners.has(event)) {
      this.listeners.set(event, new Set());
    }
    this.listeners.get(event)!.add(wrapped);
    return () => this.off(event, wrapped);
  }

  off(event: string, listener: Listener) {
    const set = this.listeners.get(event);
    if (set) {
      set.delete(listener);
    }
  }

  private dispatch(event: string, payload: unknown) {
    const set = this.listeners.get(event);
    if (set) {
      for (const listener of set) {
        try {
          listener(payload);
        } catch (err) {
          console.error(`Error in socket event listener [${event}]:`, err);
        }
      }
    }
  }

  emitTyping(conversationId: string, isTyping: boolean) {
    if (!this.socket || !this.socket.connected) return;

    const now = Date.now();
    // Throttle positive typing events to once per second
    if (isTyping && now - this.lastTypingSent < 1000) {
      return;
    }

    if (isTyping) {
      this.lastTypingSent = now;
    }

    this.socket.emit(
      'typing',
      { conversation_id: conversationId, is_typing: isTyping },
      (ack: { ok: boolean; error?: string }) => {
        // Ack received
      }
    );
  }

  isConnected(): boolean {
    return !!this.socket?.connected;
  }
}

export const socketManager = new SocketManager();

import type { Conversation, ConversationMember, Profile } from '@/types/chat';
// Utility functions for UI formatting, avatars, and animations

export function formatTime(isoString: string): string {
  try {
    const date = new Date(isoString);
    return date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  } catch {
    return '';
  }
}

export function formatDateDivider(isoString: string): string {
  try {
    const date = new Date(isoString);
    const now = new Date();
    const isToday =
      date.getDate() === now.getDate() &&
      date.getMonth() === now.getMonth() &&
      date.getFullYear() === now.getFullYear();

    const yesterday = new Date(now);
    yesterday.setDate(now.getDate() - 1);
    const isYesterday =
      date.getDate() === yesterday.getDate() &&
      date.getMonth() === yesterday.getMonth() &&
      date.getFullYear() === yesterday.getFullYear();

    if (isToday) return 'Today';
    if (isYesterday) return 'Yesterday';

    return date.toLocaleDateString([], {
      weekday: 'short',
      month: 'short',
      day: 'numeric',
      year: date.getFullYear() !== now.getFullYear() ? 'numeric' : undefined,
    });
  } catch {
    return '';
  }
}

export function formatTimeAgo(isoString: string): string {
  try {
    const date = new Date(isoString);
    const now = new Date();
    const diffSec = Math.floor((now.getTime() - date.getTime()) / 1000);

    if (diffSec < 60) return 'Just now';
    if (diffSec < 3600) return `${Math.floor(diffSec / 60)}m ago`;
    if (diffSec < 86400) return `${Math.floor(diffSec / 3600)}h ago`;
    if (diffSec < 604800) return `${Math.floor(diffSec / 86400)}d ago`;

    return date.toLocaleDateString([], { month: 'short', day: 'numeric' });
  } catch {
    return '';
  }
}

export function formatFileSize(bytes: number): string {
  if (bytes === 0) return '0 B';
  const k = 1024;
  const sizes = ['B', 'KB', 'MB', 'GB'];
  const i = Math.floor(Math.log(bytes) / Math.log(k));
  return `${parseFloat((bytes / Math.pow(k, i)).toFixed(1))} ${sizes[i]}`;
}

export function getInitials(name?: string | null): string {
  if (!name) return '?';
  const parts = name.trim().split(/\s+/);
  if (parts.length === 1) {
    return parts[0].slice(0, 2).toUpperCase();
  }
  return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase();
}

const GRADIENTS = ['#456755', '#486d78', '#876451', '#68684b', '#665e7c', '#4e7069'];

export function getAvatarGradient(identifier: string): string {
  let hash = 0;
  for (let i = 0; i < identifier.length; i++) {
    hash = identifier.charCodeAt(i) + ((hash << 5) - hash);
  }
  const index = Math.abs(hash) % GRADIENTS.length;
  return GRADIENTS[index];
}

export function truncate(text: string, maxLength: number): string {
  if (text.length <= maxLength) return text;
  return text.slice(0, maxLength) + '...';
}

export function generateUUID(): string {
  if (typeof crypto !== 'undefined' && crypto.randomUUID) {
    return crypto.randomUUID();
  }
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function (c) {
    const r = (Math.random() * 16) | 0;
    const v = c === 'x' ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  });
}

export function getMemberProfile(member?: ConversationMember | null): { id: string; username: string; display_name: string; avatar_key: string | null } | null {
  if (!member) return null;
  if (member.profiles) {
    return Array.isArray(member.profiles) ? member.profiles[0] : member.profiles;
  }

  return null;
}

export function getConversationMembers(conv?: Conversation | null): ConversationMember[] {
  if (!conv) return [];
  return conv.conversation_members || [];
}

export function getOtherMember(conv?: Conversation | null, currentUserId?: string): ConversationMember | null {
  const members = getConversationMembers(conv);
  return members.find((m) => m.user_id !== currentUserId) || null;
}
